def _require_square_token_grid(num_tokens: int, label: str):
    side = int(int(num_tokens) ** 0.5)
    if int(num_tokens) <= 0 or side * side != int(num_tokens):
        raise ValueError(
            f"{label} token count must be a positive square for current pruning/interpolation code; "
            f"got {int(num_tokens)}. Use square image resolutions or add explicit H/W grid plumbing."
        )
    return side, side


def _expert_patch_token_count(total_tokens: int, num_prefix_tokens: int, label: str) -> int:
    total_tokens = int(total_tokens)
    num_prefix_tokens = int(num_prefix_tokens)
    if num_prefix_tokens < 0:
        raise ValueError(f"{label} prefix token count must be non-negative; got {num_prefix_tokens}.")
    num_patch_tokens = total_tokens - num_prefix_tokens
    if num_patch_tokens <= 0:
        raise ValueError(
            f"{label} must contain at least one patch token; got total={total_tokens}, "
            f"prefix={num_prefix_tokens}."
        )
    return num_patch_tokens


def _pruned_patch_token_count(num_patch_tokens: int, pruning_ratio: float) -> int:
    num_patch_tokens = int(num_patch_tokens)
    pruning_ratio = float(pruning_ratio)
    if num_patch_tokens <= 0:
        raise ValueError(f"num_patch_tokens must be positive; got {num_patch_tokens}.")
    if pruning_ratio <= 0:
        raise ValueError(f"pruning_ratio must be positive when pruning is enabled; got {pruning_ratio}.")
    if pruning_ratio > 1.0:
        num_tokens_to_keep = int(pruning_ratio)
    else:
        num_tokens_to_keep = int(num_patch_tokens * (1.0 - pruning_ratio))
    return max(1, min(num_tokens_to_keep, num_patch_tokens))


def _expert_patch_grid_from_pixels(pixel_values: torch.Tensor, patch_size: int) -> tuple[int, int]:
    if pixel_values.ndim != 4:
        raise ValueError(
            "Expert pixel values must have shape [batch, channels, height, width]; "
            f"got {tuple(pixel_values.shape)}."
        )
    patch_size = int(patch_size)
    if patch_size <= 0:
        raise ValueError(f"Expert patch_size must be positive; got {patch_size}.")
    height, width = map(int, pixel_values.shape[-2:])
    if height % patch_size != 0 or width % patch_size != 0:
        raise ValueError(
            "Expert image dimensions must be divisible by patch_size; "
            f"got image={height}x{width}, patch_size={patch_size}."
        )
    return height // patch_size, width // patch_size


def _expert_patch_grid(
    total_tokens: int,
    num_prefix_tokens: int,
    label: str,
    grid_contract: str = "strict_square",
):
    num_patch_tokens = _expert_patch_token_count(total_tokens, num_prefix_tokens, label)
    if grid_contract == "legacy_floor_square":
        side = int(num_patch_tokens ** 0.5)
        if side <= 0:
            raise ValueError(f"{label} legacy patch grid is empty for {num_patch_tokens} tokens.")
        height, width = side, side
    elif grid_contract == "strict_square":
        height, width = _require_square_token_grid(num_patch_tokens, f"{label} patch")
    else:
        raise ValueError(
            "Expert patch grid contract must be 'strict_square' or "
            f"'legacy_floor_square'; got {grid_contract!r}."
        )
    return num_patch_tokens, height, width


def _expert_global_keep_indices(patch_keep_indices: torch.Tensor, num_prefix_tokens: int) -> torch.Tensor:
    if patch_keep_indices.ndim != 2:
        raise ValueError(
            "patch_keep_indices must have shape [batch, kept_patches]; "
            f"got {tuple(patch_keep_indices.shape)}."
        )
    num_prefix_tokens = int(num_prefix_tokens)
    if num_prefix_tokens < 0:
        raise ValueError(f"Expert prefix token count must be non-negative; got {num_prefix_tokens}.")
    prefix_indices = torch.arange(
        num_prefix_tokens,
        dtype=patch_keep_indices.dtype,
        device=patch_keep_indices.device,
    ).unsqueeze(0).expand(patch_keep_indices.shape[0], -1)
    return torch.cat([prefix_indices, patch_keep_indices + num_prefix_tokens], dim=1)


def _order_expert_patch_indices(patch_indices: torch.Tensor, order: str) -> torch.Tensor:
    if order == "importance":
        return patch_indices
    if order == "spatial":
        return torch.sort(patch_indices, dim=1).values
    raise ValueError(
        "expert_token_order must be 'importance' or 'spatial'; "
        f"got {order!r}."
    )


def _base_to_expanded_sequence_indices(
    base_indices: torch.Tensor,
    padding_lens: torch.Tensor,
    expert_len: int,
) -> torch.Tensor:
    """Map [padding][VL] indices into [padding][expert][VL] indices."""
    if base_indices.ndim != 2:
        raise ValueError(
            "base_indices must have shape [batch, count]; "
            f"got {tuple(base_indices.shape)}."
        )
    padding_lens = padding_lens.to(device=base_indices.device, dtype=base_indices.dtype)
    if padding_lens.ndim != 1 or padding_lens.shape[0] != base_indices.shape[0]:
        raise ValueError(
            "padding_lens must have shape [batch] matching base_indices; "
            f"got {tuple(padding_lens.shape)} for {tuple(base_indices.shape)}."
        )
    return base_indices + (base_indices >= padding_lens[:, None]).to(base_indices.dtype) * int(expert_len)


@dataclass(frozen=True)
class _PruningGuidanceIndices:
    visual_start: torch.Tensor
    instruction_start: torch.Tensor
    instruction_end: torch.Tensor
    action_start: torch.Tensor
    action_end: torch.Tensor


def _resolve_pruning_guidance_indices(
    *,
    visual_start_per_sample: torch.Tensor,
    instruction_start_per_sample: torch.Tensor,
    instruction_end_per_sample: torch.Tensor,
    attention_seq_len: int,
    action_length: int,
    padding_lens: torch.Tensor,
    expert_len: int,
    expanded_sequence: bool,
) -> _PruningGuidanceIndices:
    """Resolve base-sequence metadata against the attention matrix coordinate system."""
    attention_seq_len = int(attention_seq_len)
    action_length = int(action_length)
    if action_length <= 0 or action_length > attention_seq_len:
        raise ValueError(
            f"action_length must be in [1, {attention_seq_len}] for pruning guidance; "
            f"got {action_length}."
        )

    base_ranges = (
        visual_start_per_sample,
        instruction_start_per_sample,
        instruction_end_per_sample,
    )
    if any(item.ndim != 1 for item in base_ranges):
        raise ValueError("Pruning guidance starts/ends must each have shape [batch].")
    batch_size = visual_start_per_sample.shape[0]
    if any(item.shape[0] != batch_size for item in base_ranges):
        raise ValueError("Pruning guidance starts/ends must have matching batch dimensions.")

    visual_start = visual_start_per_sample
    instruction_start = instruction_start_per_sample
    instruction_end = instruction_end_per_sample
    if expanded_sequence:
        visual_start = _base_to_expanded_sequence_indices(
            visual_start[:, None], padding_lens, expert_len
        ).squeeze(1)
        instruction_start = _base_to_expanded_sequence_indices(
            instruction_start[:, None], padding_lens, expert_len
        ).squeeze(1)
        instruction_end = _base_to_expanded_sequence_indices(
            instruction_end[:, None], padding_lens, expert_len
        ).squeeze(1)

    # Action rows are located from the attention matrix tail. They are already in
    # expanded coordinates when expert tokens are present and must not be shifted again.
    action_start = torch.full(
        (batch_size,),
        attention_seq_len - action_length,
        dtype=visual_start.dtype,
        device=visual_start.device,
    )
    action_end = torch.full_like(action_start, attention_seq_len)
    return _PruningGuidanceIndices(
        visual_start=visual_start,
        instruction_start=instruction_start,
        instruction_end=instruction_end,
        action_start=action_start,
        action_end=action_end,
    )


def _prepare_eager_attention_collection_mask(
    attention_mask: Optional[torch.Tensor],
    *,
    batch_size: int,
    query_length: int,
    key_length: int,
    dtype: torch.dtype,
    device: torch.device,
) -> torch.Tensor:
    """Convert an SDPA causal mask into eager additive-mask semantics."""
    if not dtype.is_floating_point:
        raise TypeError(f"Attention collection requires a floating dtype; got {dtype}.")
    batch_size = int(batch_size)
    query_length = int(query_length)
    key_length = int(key_length)
    blocked = torch.finfo(dtype).min

    if attention_mask is None:
        if query_length != key_length:
            raise ValueError(
                "Cannot reconstruct an omitted SDPA causal mask for unequal query/key lengths; "
                f"got q={query_length}, k={key_length}."
            )
        query_positions = torch.arange(query_length, device=device).view(1, 1, query_length, 1)
        key_positions = torch.arange(key_length, device=device).view(1, 1, 1, key_length)
        allowed = query_positions >= key_positions
        allowed = allowed.expand(batch_size, -1, -1, -1)
    elif attention_mask.ndim == 2:
        if attention_mask.shape[0] != batch_size or attention_mask.shape[1] < key_length:
            raise ValueError(
                "2D attention mask must have shape [batch, >=key_length]; "
                f"got {tuple(attention_mask.shape)} for batch={batch_size}, key_length={key_length}."
            )
        query_positions = torch.arange(query_length, device=device).view(1, 1, query_length, 1)
        key_positions = torch.arange(key_length, device=device).view(1, 1, 1, key_length)
        allowed = (query_positions >= key_positions) & attention_mask[
            :, None, None, :key_length
        ].to(device=device, dtype=torch.bool)
    elif attention_mask.ndim == 4:
        sliced_mask = attention_mask[:, :, :query_length, :key_length].to(device=device)
        if sliced_mask.shape[0] not in {1, batch_size}:
            raise ValueError(
                "4D attention mask batch dimension must be 1 or match the attention batch; "
                f"got {tuple(sliced_mask.shape)} for batch={batch_size}."
            )
        if sliced_mask.dtype.is_floating_point:
            return sliced_mask.to(dtype=dtype)
        allowed = sliced_mask.to(dtype=torch.bool)
    else:
        raise ValueError(
            "Attention collection supports None, 2D padding masks, or 4D attention masks; "
            f"got shape {tuple(attention_mask.shape)}."
        )

    return torch.where(
        allowed,
        torch.zeros((), dtype=dtype, device=device),
        torch.full((), blocked, dtype=dtype, device=device),
    )


def _enable_bidirectional_action_attention(
    attention_mask: Optional[torch.Tensor],
    *,
    batch_size: int,
    sequence_length: int,
    action_length: int,
    dtype: torch.dtype,
    device: torch.device,
) -> torch.Tensor:
    """Keep prompt causality while opening the action-to-action submatrix."""
    batch_size = int(batch_size)
    sequence_length = int(sequence_length)
    action_length = int(action_length)
    if action_length <= 0 or action_length > sequence_length:
        raise ValueError(
            f"action_length must be in [1, {sequence_length}] for bidirectional action attention; "
            f"got {action_length}."
        )
    action_start = sequence_length - action_length

    if attention_mask is None or attention_mask.ndim == 2:
        query_positions = torch.arange(sequence_length, device=device).view(1, 1, sequence_length, 1)
        key_positions = torch.arange(sequence_length, device=device).view(1, 1, 1, sequence_length)
        allowed = (query_positions >= key_positions).expand(batch_size, -1, -1, -1).clone()
        if attention_mask is not None:
            if attention_mask.shape[0] != batch_size or attention_mask.shape[1] < sequence_length:
                raise ValueError(
                    "2D attention mask must have shape [batch, >=sequence_length]; "
                    f"got {tuple(attention_mask.shape)} for batch={batch_size}, "
                    f"sequence_length={sequence_length}."
                )
            allowed &= attention_mask[:, None, None, :sequence_length].to(
                device=device, dtype=torch.bool
            )
        allowed[:, :, action_start:, action_start:] = True
        return allowed

    if attention_mask.ndim != 4:
        raise ValueError(
            "Bidirectional action attention supports None, 2D padding masks, or 4D masks; "
            f"got shape {tuple(attention_mask.shape)}."
        )
    mask = attention_mask[:, :, :sequence_length, :sequence_length].to(device=device).clone()
    if mask.dtype.is_floating_point:
        mask[:, :, action_start:, action_start:] = 0.0
    else:
        mask[:, :, action_start:, action_start:] = True
    return mask


def _materialize_causal_attention_mask(
    attention_mask: Optional[torch.Tensor],
    *,
    batch_size: int,
    sequence_length: int,
    dtype: torch.dtype,
    device: torch.device,
) -> torch.Tensor:
    """Return an additive causal mask even when SDPA omitted it."""
    return _prepare_eager_attention_collection_mask(
        attention_mask,
        batch_size=batch_size,
        query_length=sequence_length,
        key_length=sequence_length,
        dtype=dtype,
        device=device,
    )


def _restrict_expert_kv_to_action_rows(
    attention_mask: Optional[torch.Tensor],
    *,
    batch_size: int,
    sequence_length: int,
    expert_len: int,
    action_length: int,
    padding_lens: Optional[torch.Tensor],
    dtype: torch.dtype,
    device: torch.device,
) -> torch.Tensor:
    """Make expert K/V private to action query rows (mask-only ablation).

    Layout is ``[padding][expert][vl]`` with total ``sequence_length``. Blocks
    exactly the cells whose query row is a VL non-action token
    (``row in [pad+expert_len, sequence_length-action_length)``) and whose key
    column is an expert token (``col in [pad, pad+expert_len)``). Expert query
    rows, padding rows, and the trailing ``action_length`` action rows keep
    their existing visibility.
    """
    batch_size = int(batch_size)
    sequence_length = int(sequence_length)
    expert_len = int(expert_len)
    action_length = int(action_length)
    if expert_len <= 0:
        raise ValueError(f"expert_len must be positive; got {expert_len}.")
    if action_length <= 0 or action_length > sequence_length:
        raise ValueError(
            f"action_length must be in [1, {sequence_length}] for expert-private masking; "
            f"got {action_length}."
        )
    if padding_lens is None:
        padding_lens = torch.zeros(batch_size, dtype=torch.long, device=device)
    padding_lens = padding_lens.to(device=device, dtype=torch.long)
    if padding_lens.shape != (batch_size,):
        raise ValueError(
            f"padding_lens must have shape {(batch_size,)}; got {tuple(padding_lens.shape)}."
        )

    positions = torch.arange(sequence_length, device=device)
    row_positions = positions.view(1, 1, sequence_length, 1)
    col_positions = positions.view(1, 1, 1, sequence_length)
    pad = padding_lens.view(batch_size, 1, 1, 1)
    vl_non_action_rows = (row_positions >= pad + expert_len) & (
        row_positions < sequence_length - action_length
    )
    expert_cols = (col_positions >= pad) & (col_positions < pad + expert_len)
    blocked = vl_non_action_rows & expert_cols  # [batch, 1, seq, seq]

    if attention_mask is None or attention_mask.ndim == 2:
        allowed = (row_positions >= col_positions).expand(batch_size, 1, -1, -1).clone()
        if attention_mask is not None:
            if attention_mask.shape[0] != batch_size or attention_mask.shape[1] < sequence_length:
                raise ValueError(
                    "2D attention mask must have shape [batch, >=sequence_length]; "
                    f"got {tuple(attention_mask.shape)} for batch={batch_size}, "
                    f"sequence_length={sequence_length}."
                )
            allowed &= attention_mask[:, None, None, :sequence_length].to(
                device=device, dtype=torch.bool
            )
        return allowed & ~blocked

    if attention_mask.ndim != 4:
        raise ValueError(
            "Expert-private masking supports None, 2D padding masks, or 4D masks; "
            f"got shape {tuple(attention_mask.shape)}."
        )
    mask = attention_mask[:, :, :sequence_length, :sequence_length].to(device=device).clone()
    if mask.dtype.is_floating_point:
        blocked_value = torch.finfo(mask.dtype).min
        mask = mask.masked_fill(blocked.to(mask.device), blocked_value)
    else:
        mask = mask & ~blocked.to(mask.device)
    return mask


def _expand_base_token_mask(
    base_mask: torch.Tensor,
    *,
    padding_lens: torch.Tensor,
    expert_len: int,
    expert_value: bool,
) -> torch.Tensor:
    """Expand [padding][VL] metadata into [padding][expert][VL] coordinates."""
    if base_mask.ndim != 2:
        raise ValueError(f"base_mask must have shape [batch, sequence]; got {tuple(base_mask.shape)}.")
    batch_size, base_length = base_mask.shape
    expert_len = int(expert_len)
    if expert_len < 0:
        raise ValueError(f"expert_len must be non-negative; got {expert_len}.")
    padding_lens = padding_lens.to(device=base_mask.device, dtype=torch.long)
    if padding_lens.shape != (batch_size,):
        raise ValueError(
            f"padding_lens must have shape {(batch_size,)}; got {tuple(padding_lens.shape)}."
        )

    full_length = base_length + expert_len
    positions = torch.arange(full_length, device=base_mask.device).unsqueeze(0).expand(batch_size, -1)
    pad_lens = padding_lens[:, None]
    is_padding = positions < pad_lens
    is_expert = (positions >= pad_lens) & (positions < pad_lens + expert_len)
    base_indices = torch.where(is_padding, positions, positions - expert_len).clamp(0, base_length - 1)
    expanded = torch.gather(base_mask.to(torch.bool), 1, base_indices)
    return torch.where(is_expert, torch.full_like(expanded, bool(expert_value)), expanded)


def _build_action_restriction_mask(
    causal_mask: Optional[torch.Tensor],
    *,
    visual_pos_mask: torch.Tensor,
    action_length: int,
    mode: str,
    dtype: torch.dtype,
    device: torch.device,
    expert_len: int = 0,
    padding_lens: Optional[torch.Tensor] = None,
    roi_pos_mask: Optional[torch.Tensor] = None,
) -> torch.Tensor:
    """Restrict action-query keys in base or [padding][expert][VL] coordinates."""
    if mode not in {"pre_image", "non_image", "roi_image"}:
        raise ValueError(f"Unsupported action attention restriction mode: {mode!r}.")
    if visual_pos_mask.ndim != 2:
        raise ValueError(
            "visual_pos_mask must have shape [batch, base_sequence]; "
            f"got {tuple(visual_pos_mask.shape)}."
        )
    base_visual_mask = visual_pos_mask.to(device=device, dtype=torch.bool)
    batch_size, base_length = base_visual_mask.shape
    expert_len = int(expert_len)
    full_length = base_length + expert_len
    action_length = int(action_length)
    if action_length <= 0 or action_length > base_length:
        raise ValueError(
            f"action_length must be in [1, {base_length}] for action restriction; got {action_length}."
        )

    if padding_lens is None:
        padding_lens = torch.zeros(batch_size, dtype=torch.long, device=device)
    else:
        padding_lens = padding_lens.to(device=device, dtype=torch.long)

    mask = _materialize_causal_attention_mask(
        causal_mask,
        batch_size=batch_size,
        sequence_length=full_length,
        dtype=dtype,
        device=device,
    )
    blocked = torch.finfo(dtype).min
    query_positions = torch.arange(full_length, device=device).view(1, 1, full_length, 1)
    key_positions = torch.arange(full_length, device=device).view(1, 1, 1, full_length)
    action_start = full_length - action_length
    action_queries = query_positions >= action_start
    action_keys = key_positions >= action_start

    expanded_visual_mask = _expand_base_token_mask(
        base_visual_mask,
        padding_lens=padding_lens,
        expert_len=expert_len,
        expert_value=True,
    )
    if mode == "pre_image":
        has_image = expanded_visual_mask.any(dim=1)
        image_start = expanded_visual_mask.to(torch.long).argmax(dim=1)
        image_start = torch.where(
            has_image,
            image_start,
            torch.full_like(image_start, full_length),
        )
        forbidden_keys = key_positions < image_start.view(batch_size, 1, 1, 1)
    else:
        allowed_visual_mask = expanded_visual_mask
        if mode == "roi_image":
            if roi_pos_mask is None or roi_pos_mask.shape != base_visual_mask.shape:
                raise ValueError(
                    "roi_pos_mask must match visual_pos_mask for roi_image restriction; "
                    f"got {None if roi_pos_mask is None else tuple(roi_pos_mask.shape)}."
                )
            allowed_visual_mask = _expand_base_token_mask(
                roi_pos_mask.to(device=device, dtype=torch.bool),
                padding_lens=padding_lens,
                expert_len=expert_len,
                expert_value=True,
            )
        allowed_keys = allowed_visual_mask[:, None, None, :] | action_keys
        forbidden_keys = ~allowed_keys

    return mask.masked_fill(action_queries & forbidden_keys, blocked)


def _validate_pruning_before_expert_injection(
    *,
    pruning_completion_layer: int,
    expert_injection_layers,
) -> None:
    layers = sorted(int(layer) for layer in expert_injection_layers)
    if not layers:
        return
    pruning_completion_layer = int(pruning_completion_layer)
    if pruning_completion_layer >= layers[0]:
        raise ValueError(
            "Qwen-guided pruning must finish before the first expert injection layer because "
            "mask/position lengths are precomputed for pruned QKV; "
            f"got pruning completion layer {pruning_completion_layer} and first expert injection "
            f"layer {layers[0]}."
        )


def _resolve_pruning_layer_index(
    layer: int,
    *,
    num_layers: int,
    index_base: str,
    label: str,
) -> int:
    layer = int(layer)
    num_layers = int(num_layers)
    if index_base not in {"zero", "one"}:
        raise ValueError(
            "pruning_layer_index_base must be 'zero' or 'one'; "
            f"got {index_base!r}."
        )
    if layer < 0:
        layer = num_layers + layer
    elif index_base == "one":
        if layer == 0:
            raise ValueError(f"{label} must be positive for one-based indexing; got {layer}.")
        layer -= 1
    if layer < 0 or layer >= num_layers:
        raise ValueError(
            f"{label} resolves to code layer {layer}, outside [0, {num_layers - 1}]."
        )
    return layer


def _uses_pruning_attention_aggregation(mode: str) -> bool:
    return mode in {"mean_layers", "vote", "intersection", "action_task_mean"}


def _combine_action_task_attention(
    action_attention: torch.Tensor,
    task_attention: torch.Tensor,
    *,
    contract: str,
) -> torch.Tensor:
    if contract in {"action_only", "historical_action_only"}:
        return action_attention
    if contract in {"historical_joint_mean", "joint_mean"}:
        return (action_attention + task_attention) / 2.0
    raise ValueError(
        "action_task_attention_contract must be 'historical_joint_mean', 'joint_mean', "
        "'action_only', or the compatibility alias 'historical_action_only'; "
        f"got {contract!r}."
    )


class Qwen3VLVisionMLP(nn.Module):
    def __init__(self, config):
        super().__init__()
        self.hidden_size = config.hidden_size
        self.intermediate_size = config.intermediate_size
        self.linear_fc1 = nn.Linear(self.hidden_size, self.intermediate_size, bias=True)
        self.linear_fc2 = nn.Linear(self.intermediate_size, self.hidden_size, bias=True)
        self.act_fn = ACT2FN[config.hidden_act]

    def forward(self, hidden_state):
        return self.linear_fc2(self.act_fn(self.linear_fc1(hidden_state)))


class Qwen3VLVisionPatchEmbed(nn.Module):
    def __init__(self, config) -> None:
        super().__init__()
        self.patch_size = config.patch_size
        self.temporal_patch_size = config.temporal_patch_size
        self.in_channels = config.in_channels
        self.embed_dim = config.hidden_size

        kernel_size = [self.temporal_patch_size, self.patch_size, self.patch_size]
        self.proj = nn.Conv3d(self.in_channels, self.embed_dim, kernel_size=kernel_size, stride=kernel_size, bias=True)

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        target_dtype = self.proj.weight.dtype
        hidden_states = hidden_states.view(
            -1, self.in_channels, self.temporal_patch_size, self.patch_size, self.patch_size
        )
        hidden_states = self.proj(hidden_states.to(dtype=target_dtype)).view(-1, self.embed_dim)
        return hidden_states


class Qwen3VLVisionRotaryEmbedding(nn.Module):
    inv_freq: torch.Tensor  # fix linting for `register_buffer`

    def __init__(self, dim: int, theta: float = 10000.0) -> None:
        super().__init__()
        inv_freq = 1.0 / (theta ** (torch.arange(0, dim, 2, dtype=torch.float) / dim))
        self.register_buffer("inv_freq", inv_freq, persistent=False)

    def forward(self, seqlen: int) -> torch.Tensor:
        seq = torch.arange(seqlen, device=self.inv_freq.device, dtype=self.inv_freq.dtype)
        freqs = torch.outer(seq, self.inv_freq)
        return freqs


class Qwen3VLVisionPatchMerger(nn.Module):
    def __init__(self, config: Qwen3VLVisionConfig, use_postshuffle_norm=False) -> None:
        super().__init__()
        self.hidden_size = config.hidden_size * (config.spatial_merge_size**2)
        self.use_postshuffle_norm = use_postshuffle_norm
        self.norm = nn.LayerNorm(self.hidden_size if use_postshuffle_norm else config.hidden_size, eps=1e-6)
        self.linear_fc1 = nn.Linear(self.hidden_size, self.hidden_size)
        self.act_fn = nn.GELU()
        self.linear_fc2 = nn.Linear(self.hidden_size, config.out_hidden_size)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = self.norm(x.view(-1, self.hidden_size) if self.use_postshuffle_norm else x).view(-1, self.hidden_size)
        x = self.linear_fc2(self.act_fn(self.linear_fc1(x)))
        return x


def rotate_half(x):
    """Rotates half the hidden dims of the input."""
    x1 = x[..., : x.shape[-1] // 2]
    x2 = x[..., x.shape[-1] // 2 :]
    return torch.cat((-x2, x1), dim=-1)


def apply_rotary_pos_emb_vision(
    q: torch.Tensor, k: torch.Tensor, cos: torch.Tensor, sin: torch.Tensor
) -> tuple[torch.Tensor, torch.Tensor]:
    orig_q_dtype = q.dtype
    orig_k_dtype = k.dtype
    q, k = q.float(), k.float()
    cos, sin = cos.unsqueeze(-2).float(), sin.unsqueeze(-2).float()
    q_embed = (q * cos) + (rotate_half(q) * sin)
    k_embed = (k * cos) + (rotate_half(k) * sin)
    q_embed = q_embed.to(orig_q_dtype)
    k_embed = k_embed.to(orig_k_dtype)
    return q_embed, k_embed


def repeat_kv(hidden_states: torch.Tensor, n_rep: int) -> torch.Tensor:
    """
    This is the equivalent of torch.repeat_interleave(x, dim=1, repeats=n_rep). The hidden states go from (batch,
    num_key_value_heads, seqlen, head_dim) to (batch, num_attention_heads, seqlen, head_dim)
    """
    batch, num_key_value_heads, slen, head_dim = hidden_states.shape
    if n_rep == 1:
        return hidden_states
    hidden_states = hidden_states[:, :, None, :, :].expand(batch, num_key_value_heads, n_rep, slen, head_dim)
    return hidden_states.reshape(batch, num_key_value_heads * n_rep, slen, head_dim)


def eager_attention_forward(
    module: nn.Module,
    query: torch.Tensor,
    key: torch.Tensor,
    value: torch.Tensor,
    attention_mask: Optional[torch.Tensor],
    scaling: float,
    dropout: float = 0.0,
    **kwargs: Unpack[TransformersKwargs],
):
    key_states = repeat_kv(key, module.num_key_value_groups)
    value_states = repeat_kv(value, module.num_key_value_groups)

    attn_weights = torch.matmul(query, key_states.transpose(2, 3)) * scaling
    if attention_mask is not None:
        causal_mask = attention_mask[:, :, :, : key_states.shape[-2]]
        attn_weights = attn_weights + causal_mask

    attn_weights = nn.functional.softmax(attn_weights, dim=-1, dtype=torch.float32).to(query.dtype)
    attn_weights = nn.functional.dropout(attn_weights, p=dropout, training=module.training)
    attn_output = torch.matmul(attn_weights, value_states)
    attn_output = attn_output.transpose(1, 2).contiguous()

    return attn_output, attn_weights


class Qwen3VLVisionAttention(nn.Module):
    def __init__(self, config: Qwen3VLVisionConfig) -> None:
        super().__init__()
        self.dim = config.hidden_size
        self.num_heads = config.num_heads
        self.head_dim = self.dim // self.num_heads
        self.num_key_value_groups = 1  # needed for eager attention
        self.qkv = nn.Linear(self.dim, self.dim * 3, bias=True)
        self.proj = nn.Linear(self.dim, self.dim)
        self.scaling = self.head_dim**-0.5
        self.config = config
        self.attention_dropout = 0.0
        self.is_causal = False

    def forward(
        self,
        hidden_states: torch.Tensor,
        cu_seqlens: torch.Tensor,
        rotary_pos_emb: Optional[torch.Tensor] = None,
        position_embeddings: Optional[tuple[torch.Tensor, torch.Tensor]] = None,
        **kwargs,
    ) -> torch.Tensor:
        # Pop side-channel collector for SigLIP MOT QKV capture (does not affect normal forward)
        siglip_qkv_collector = kwargs.pop('siglip_qkv_collector', None)
        seq_length = hidden_states.shape[0]
        query_states, key_states, value_states = (
            self.qkv(hidden_states).reshape(seq_length, 3, self.num_heads, -1).permute(1, 0, 2, 3).unbind(0)
        )
        cos, sin = position_embeddings
        query_states, key_states = apply_rotary_pos_emb_vision(query_states, key_states, cos, sin)
        # Capture QKV after 2D vision RoPE for SigLIP MOT injection into LLM attention
        # Shape: [seq_len, num_heads, head_dim] — reshaped to batched format in training script
        if siglip_qkv_collector is not None:
            siglip_qkv_collector['query'] = query_states
            siglip_qkv_collector['key'] = key_states
            siglip_qkv_collector['value'] = value_states
            siglip_qkv_collector['cu_seqlens'] = cu_seqlens

        query_states = query_states.transpose(0, 1).unsqueeze(0)
        key_states = key_states.transpose(0, 1).unsqueeze(0)
        value_states = value_states.transpose(0, 1).unsqueeze(0)

        attention_interface: Callable = eager_attention_forward
        if self.config._attn_implementation != "eager":
            attention_interface = ALL_ATTENTION_FUNCTIONS[self.config._attn_implementation]

        if self.config._attn_implementation == "flash_attention_2":
            # Flash Attention 2: Use cu_seqlens for variable length attention
            max_seqlen = (cu_seqlens[1:] - cu_seqlens[:-1]).max()
            attn_output, _ = attention_interface(
                self,
                query_states,
                key_states,
                value_states,
                attention_mask=None,
                scaling=self.scaling,
                dropout=0.0 if not self.training else self.attention_dropout,
                cu_seq_lens_q=cu_seqlens,
                cu_seq_lens_k=cu_seqlens,
                max_length_q=max_seqlen,
                max_length_k=max_seqlen,
                is_causal=False,
                **kwargs,
            )
        else:
            # Other implementations: Process each chunk separately
            lengths = cu_seqlens[1:] - cu_seqlens[:-1]
            splits = [
                torch.split(tensor, lengths.tolist(), dim=2) for tensor in (query_states, key_states, value_states)
            ]

            attn_outputs = [
                attention_interface(
                    self,
                    q,
                    k,
                    v,
                    attention_mask=None,
                    scaling=self.scaling,
                    dropout=0.0 if not self.training else self.attention_dropout,
                    is_causal=False,
                    **kwargs,
                )[0]
                for q, k, v in zip(*splits)
            ]
            attn_output = torch.cat(attn_outputs, dim=1)

        attn_output = attn_output.reshape(seq_length, -1).contiguous()
        attn_output = self.proj(attn_output)
        return attn_output


class Qwen3VLVisionBlock(GradientCheckpointingLayer):
    def __init__(self, config, attn_implementation: str = "sdpa") -> None:
        super().__init__()
        self.norm1 = nn.LayerNorm(config.hidden_size, eps=1e-6)
        self.norm2 = nn.LayerNorm(config.hidden_size, eps=1e-6)
        self.attn = Qwen3VLVisionAttention(config=config)
        self.mlp = Qwen3VLVisionMLP(config=config)

    def forward(
        self,
        hidden_states: torch.Tensor,
        cu_seqlens: torch.Tensor,
        rotary_pos_emb: Optional[torch.Tensor] = None,
        position_embeddings: Optional[tuple[torch.Tensor, torch.Tensor]] = None,
        **kwargs,
    ) -> torch.Tensor:
        hidden_states = hidden_states + self.attn(
            self.norm1(hidden_states),
            cu_seqlens=cu_seqlens,
            rotary_pos_emb=rotary_pos_emb,
            position_embeddings=position_embeddings,
            **kwargs,
        )
        hidden_states = hidden_states + self.mlp(self.norm2(hidden_states))
        return hidden_states


class Qwen3VLTextRotaryEmbedding(nn.Module):
    inv_freq: torch.Tensor  # fix linting for `register_buffer`

    def __init__(self, config: Qwen3VLTextConfig, device=None):
        super().__init__()
        if hasattr(config, "rope_scaling") and config.rope_scaling is not None:
            self.rope_type = config.rope_scaling.get("rope_type", "default")
        else:
            self.rope_type = "default"
        self.max_seq_len_cached = config.max_position_embeddings
        self.original_max_seq_len = config.max_position_embeddings

        self.config = config
        self.rope_init_fn = ROPE_INIT_FUNCTIONS[self.rope_type]

        inv_freq, self.attention_scaling = self.rope_init_fn(self.config, device)
        self.register_buffer("inv_freq", inv_freq, persistent=False)
        self.original_inv_freq = self.inv_freq

        self.mrope_section = config.rope_scaling.get("mrope_section", [24, 20, 20])

    def apply_interleaved_mrope(self, freqs, mrope_section):
        """Apply interleaved MRoPE to 3D rotary embeddings.
        Reorganizes frequency layout from chunked [TTT...HHH...WWW] to
        interleaved [THTHWHTHW...TT], preserving frequency continuity.
        args:
            x: (3, bs, seq_len, head_dim // 2)
            mrope_section: (3,)
        returns:
            x_t: (bs, seq_len, head_dim // 2)
        """
        freqs_t = freqs[0]  # just overwrite the first dimension T
        for dim, offset in enumerate((1, 2), start=1):  # H, W
            length = mrope_section[dim] * 3
            idx = slice(offset, length, 3)
            freqs_t[..., idx] = freqs[dim, ..., idx]
        return freqs_t

    @torch.no_grad()
    @dynamic_rope_update  # power user: used with advanced RoPE types (e.g. dynamic rope)
    def forward(self, x, position_ids):
        # In contrast to other models, Qwen3VL has different position ids for the grids
        # So we expand the inv_freq to shape (3, ...)
        if position_ids.ndim == 2:
            position_ids = position_ids[None, ...].expand(3, position_ids.shape[0], -1)
        inv_freq_expanded = self.inv_freq[None, None, :, None].float().expand(3, position_ids.shape[1], -1, 1)
        position_ids_expanded = position_ids[:, :, None, :].float()  # shape (3, bs, 1, positions)

        device_type = x.device.type if isinstance(x.device.type, str) and x.device.type != "mps" else "cpu"
        with torch.autocast(device_type=device_type, enabled=False):  # Force float32
            freqs = (inv_freq_expanded.float() @ position_ids_expanded.float()).transpose(2, 3)
            freqs = self.apply_interleaved_mrope(freqs, self.mrope_section)
            emb = torch.cat((freqs, freqs), dim=-1)
            cos = emb.cos() * self.attention_scaling
            sin = emb.sin() * self.attention_scaling

        return cos.to(dtype=x.dtype), sin.to(dtype=x.dtype)


@use_kernel_forward_from_hub("RMSNorm")
class Qwen3VLTextRMSNorm(nn.Module):
    def __init__(self, hidden_size, eps: float = 1e-6) -> None:
        """
        Qwen3VLTextRMSNorm is equivalent to T5LayerNorm
        """
        super().__init__()
        self.weight = nn.Parameter(torch.ones(hidden_size))
        self.variance_epsilon = eps

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        input_dtype = hidden_states.dtype
        hidden_states = hidden_states.to(torch.float32)
        variance = hidden_states.pow(2).mean(-1, keepdim=True)
        hidden_states = hidden_states * torch.rsqrt(variance + self.variance_epsilon)
        return self.weight * hidden_states.to(input_dtype)

    def extra_repr(self):
        return f"{tuple(self.weight.shape)}, eps={self.variance_epsilon}"


def apply_rotary_pos_emb(q, k, cos, sin, position_ids=None, unsqueeze_dim=1):
    """Applies Rotary Position Embedding to the query and key tensors.

    Args:
        q (`torch.Tensor`): The query tensor.
        k (`torch.Tensor`): The key tensor.
        cos (`torch.Tensor`): The cosine part of the rotary embedding.
        sin (`torch.Tensor`): The sine part of the rotary embedding.
        position_ids (`torch.Tensor`, *optional*):
            Deprecated and unused.
        unsqueeze_dim (`int`, *optional*, defaults to 1):
            The 'unsqueeze_dim' argument specifies the dimension along which to unsqueeze cos[position_ids] and
            sin[position_ids] so that they can be properly broadcasted to the dimensions of q and k. For example, note
            that cos[position_ids] and sin[position_ids] have the shape [batch_size, seq_len, head_dim]. Then, if q and
            k have the shape [batch_size, heads, seq_len, head_dim], then setting unsqueeze_dim=1 makes
            cos[position_ids] and sin[position_ids] broadcastable to the shapes of q and k. Similarly, if q and k have
            the shape [batch_size, seq_len, heads, head_dim], then set unsqueeze_dim=2.
    Returns:
        `tuple(torch.Tensor)` comprising of the query and key tensors rotated using the Rotary Position Embedding.
    """
    cos = cos.unsqueeze(unsqueeze_dim)
    sin = sin.unsqueeze(unsqueeze_dim)
    q_embed = (q * cos) + (rotate_half(q) * sin)
    k_embed = (k * cos) + (rotate_half(k) * sin)
    return q_embed, k_embed


class Qwen3VLTextAttention(nn.Module):
    """Multi-headed attention from 'Attention Is All You Need' paper"""

    def __init__(self, config: Qwen3VLTextConfig, layer_idx: int):
        super().__init__()
        self.config = config
        self.layer_idx = layer_idx
        self.head_dim = getattr(config, "head_dim", config.hidden_size // config.num_attention_heads)
        self.num_key_value_groups = config.num_attention_heads // config.num_key_value_heads
        self.scaling = self.head_dim**-0.5
        self.attention_dropout = config.attention_dropout
        self.is_causal = True
        
        # 是否对 dinov3 QKV 应用 Qwen 1D RoPE（覆盖原来的 2D RoPE）
        self.dinov3_use_qwen_rope = getattr(config, 'dinov3_use_qwen_rope', False)

        self.q_proj = nn.Linear(
            config.hidden_size, config.num_attention_heads * self.head_dim, bias=config.attention_bias
        )
        self.k_proj = nn.Linear(
            config.hidden_size, config.num_key_value_heads * self.head_dim, bias=config.attention_bias
        )
        self.v_proj = nn.Linear(
            config.hidden_size, config.num_key_value_heads * self.head_dim, bias=config.attention_bias
        )
        self.o_proj = nn.Linear(
            config.num_attention_heads * self.head_dim, config.hidden_size, bias=config.attention_bias
        )
        self.q_norm = Qwen3VLTextRMSNorm(self.head_dim, eps=config.rms_norm_eps)  # unlike olmo, only on the head dim!
        self.k_norm = Qwen3VLTextRMSNorm(
            self.head_dim, eps=config.rms_norm_eps
        )  # thus post q_norm does not need reshape

    @deprecate_kwarg("past_key_value", new_name="past_key_values", version="4.58")
    def forward(
        self,
        hidden_states: torch.Tensor,
        position_embeddings: tuple[torch.Tensor, torch.Tensor],
        attention_mask: Optional[torch.Tensor],
        past_key_values: Optional[Cache] = None,
        cache_position: Optional[torch.LongTensor] = None,
        output_attentions: bool = False,
        **kwargs: Unpack[FlashAttentionKwargs],
    ) -> tuple[torch.Tensor, Optional[torch.Tensor]]:
        input_shape = hidden_states.shape[:-1]
        hidden_shape = (*input_shape, -1, self.head_dim)

        attention_implementation = kwargs.pop(
            "attention_implementation_override",
            self.config._attn_implementation,
        )
        if attention_implementation is None:
            attention_implementation = "eager"
        if attention_implementation != "eager" and attention_implementation not in ALL_ATTENTION_FUNCTIONS:
            raise ValueError(
                f"Unsupported attention implementation override: {attention_implementation!r}."
            )

        # 获取 dinov3 QKV（如果有的话）
        dinov3_qkv = kwargs.get('dinov3_qkv', None)
        dinov3_len = kwargs.get('dinov3_len', 0)

        # 计算 image 部分的 QKV
        query_states = self.q_norm(self.q_proj(hidden_states).view(hidden_shape)).transpose(1, 2)
        key_states = self.k_norm(self.k_proj(hidden_states).view(hidden_shape)).transpose(1, 2)
        value_states = self.v_proj(hidden_states).view(hidden_shape).transpose(1, 2)

        cos, sin = position_embeddings  # [4, 860, 128]
        image_seq_len = query_states.shape[2]  # 这里是 [padding][vl] 的总长度
        
        # 获取 padding_lens，用于正确处理 [padding][dinov3][vl] 顺序
        padding_lens = kwargs.get('padding_lens', None)
        
        # 如果有 dinov3 QKV，需要拼接
        if dinov3_qkv is not None:
            # 当前层有 dinov3：需要按 [padding][dinov3][vl] 顺序拼接 QKV
            # 提取 dinov3 的 QKV (已经加过 2D RoPE)
            query_states_dinov3 = dinov3_qkv['query']  # [batch, num_heads, dinov3_len, head_dim]
            key_states_dinov3 = dinov3_qkv['key']
            value_states_dinov3 = dinov3_qkv['value']
            
            batch_size = query_states.shape[0]
            num_heads_q = query_states.shape[1]  # query 的 head 数量
            num_heads_kv = key_states.shape[1]   # key/value 的 head 数量 (GQA 模式下可能不同)
            head_dim = query_states.shape[3]
            full_seq_len = dinov3_len + image_seq_len
            
            # ============================================================
            # 📌 向量化实现：使用 torch.gather 避免 for 循环
            # ============================================================
            # 策略：先拼接为 [padding][vl][dinov3]，再通过 gather 重排为 [padding][dinov3][vl]
            
            # Step 1: 拼接为 [padding][vl][dinov3]
            # query_states: [batch, num_heads_q, image_seq_len, head_dim] 顺序是 [padding][vl]
            # key_states: [batch, num_heads_kv, image_seq_len, head_dim]
            # query_states_dinov3: [batch, num_heads_q, dinov3_len, head_dim]
            query_concat = torch.cat([query_states, query_states_dinov3], dim=2)  # [batch, num_heads_q, full_seq_len, head_dim]
            key_concat = torch.cat([key_states, key_states_dinov3], dim=2)  # [batch, num_heads_kv, full_seq_len, head_dim]
            value_concat = torch.cat([value_states, value_states_dinov3], dim=2)
            
            # Step 2: 向量化构建重排索引
            # 目标顺序: [padding][dinov3][vl]
            # 原始顺序: [padding][vl][dinov3] = [0..image_seq_len-1, image_seq_len..full_seq_len-1]
            # 
            # 对于重排后位置 j：
            #   - j < pad_len: 取 j (padding 部分不变)
            #   - pad_len <= j < pad_len + dinov3_len: 取 image_seq_len + (j - pad_len) (从 dinov3 部分取)
            #   - j >= pad_len + dinov3_len: 取 j - dinov3_len (从 vl 部分取)
            
            device = query_states.device
            
            # 创建位置索引 [batch, full_seq_len]
            positions = torch.arange(full_seq_len, device=device).unsqueeze(0).expand(batch_size, -1)
            
            if padding_lens is not None:
                # 训练模式：每个样本可能有不同的 padding 长度
                pad_lens = padding_lens[:, None]  # [batch, 1]
            else:
                # 推理模式：没有 padding
                pad_lens = torch.zeros(batch_size, 1, dtype=torch.long, device=device)
            
            # 计算三个区域的掩码
            is_padding = positions < pad_lens  # [batch, full_seq_len]
            is_dinov3 = (positions >= pad_lens) & (positions < pad_lens + dinov3_len)
            is_vl = positions >= pad_lens + dinov3_len
            
            # 计算重排索引
            # padding 部分: 索引不变
            # dinov3 部分: 索引 = image_seq_len + (position - pad_len)
            # vl 部分: 索引 = position - dinov3_len
            reorder_indices = torch.zeros(batch_size, full_seq_len, dtype=torch.long, device=device)
            reorder_indices = torch.where(is_padding, positions, reorder_indices)
            reorder_indices = torch.where(is_dinov3, image_seq_len + (positions - pad_lens), reorder_indices)
            reorder_indices = torch.where(is_vl, positions - dinov3_len, reorder_indices)
            
            # 扩展索引用于 gather（GQA 模式下 query 和 key/value 的 head 数量不同）
            # query: [batch, num_heads_q, full_seq_len, head_dim]
            # key/value: [batch, num_heads_kv, full_seq_len, head_dim]
            gather_indices_q = reorder_indices[:, None, :, None].expand(batch_size, num_heads_q, full_seq_len, head_dim)
            gather_indices_kv = reorder_indices[:, None, :, None].expand(batch_size, num_heads_kv, full_seq_len, head_dim)
            
            # Step 3: 使用 gather 进行重排
            query_states = torch.gather(query_concat, 2, gather_indices_q)
            key_states = torch.gather(key_concat, 2, gather_indices_kv)
            value_states = torch.gather(value_concat, 2, gather_indices_kv)
            
            # Step 4: 向量化应用 RoPE
            # Position Embeddings 已经按 [padding][dinov3][vl] 顺序构建
            # cos, sin: [batch, full_seq_len, head_dim]
            
            # 构建 RoPE 应用掩码
            # - Padding 部分：不应用 RoPE（保持原样）
            # - DINOv3 部分：根据 dinov3_use_qwen_rope 决定
            # - VL 部分：应用 RoPE
            
            # 为了向量化，我们先对所有位置应用 RoPE，然后用掩码选择性保留
            # 对于 padding 部分，RoPE 结果会被丢弃（使用原始值）
            
            # 应用 RoPE 到所有位置
            query_with_rope, key_with_rope = apply_rotary_pos_emb(query_states, key_states, cos, sin)
            
            # 创建 RoPE 应用掩码: [batch, 1, full_seq_len, 1]
            # Padding 部分不应用 RoPE
            rope_mask = ~is_padding  # [batch, full_seq_len]
            
            if not self.dinov3_use_qwen_rope:
                # DINOv3 部分也不应用 Qwen RoPE（保留其原有的 2D RoPE）
                rope_mask = rope_mask & ~is_dinov3
            
            rope_mask = rope_mask[:, None, :, None]  # [batch, 1, full_seq_len, 1]
            
            # 选择性应用 RoPE
            query_states = torch.where(rope_mask, query_with_rope, query_states)
            key_states = torch.where(rope_mask, key_with_rope, key_states)
            
        else:
            # 没有 dinov3：前面的层只处理 image 部分
            # Position Embedding 处理：
            # 前面层只有 [padding][vl]，使用对应的 position embedding
            if dinov3_len > 0 and padding_lens is not None:
                # 有 dinov3 配置但当前层不使用
                # 向量化处理：只对 VL 部分应用 RoPE
                batch_size = query_states.shape[0]
                device = query_states.device
                
                # cos, sin 是按 [padding][dinov3][vl] 顺序的完整 position embeddings
                # 但当前层只有 [padding][vl]，需要从 cos/sin 中提取 VL 部分
                # 
                # 📌 重要：VL 部分始终从位置 dinov3_len 开始，不受 padding 影响
                # 即：第一个有效 VL token 使用位置 dinov3_len，第二个使用 dinov3_len+1，...
                
                # 创建位置索引用于 gather cos/sin
                positions = torch.arange(image_seq_len, device=device).unsqueeze(0).expand(batch_size, -1)
                pad_lens = padding_lens[:, None]  # [batch, 1]
                
                is_padding = positions < pad_lens  # [batch, image_seq_len]
                is_vl = ~is_padding
                
                # VL 部分的 RoPE 位置索引（gather 进 slot-indexed 的 [pad][dino][vl] cos/sin 表）：
                # cos/sin 的 full-slot k 存放 VL 位置值 (k - pad_len)；base 位置 j 的 VL token
                # 落在 full-slot dinov3_len + j（pad_len 抵消），故正确 gather 索引 = dinov3_len + positions。
                # BUGFIX(2026-08-19)：原为 `dinov3_len + (positions - pad_len)`（少了 +pad_len），
                # 在左 padding 变长 batch 的非注入层上给 VL/action token 错位 RoPE（mRoPE 空间 H/W 打乱）；
                # 只在 vl_position_contract=historical_expert_offset_all_layers 下触发（本 campaign 用
                # preserve_qwen_mrope 不走此路径）。修法经动态 harness 验证（tensorflow_verify/probe_padding_rope_bug.py：
                # historical 下 FAIL→修法后 PASS 1.7e-6）。
                rope_indices = dinov3_len + positions  # [batch, image_seq_len]
                # Padding 位置仍由下面的 is_padding 置 0（结果被 mask 丢弃）。
                
                # Padding 部分使用占位值 0（结果会被 mask 丢弃）
                rope_indices = torch.where(is_padding, torch.zeros_like(rope_indices), rope_indices)
                
                # gather cos/sin: [batch, image_seq_len, head_dim]
                head_dim = cos.shape[-1]
                gather_indices_rope = rope_indices[:, :, None].expand(batch_size, image_seq_len, head_dim)
                cos_gathered = torch.gather(cos, 1, gather_indices_rope)
                sin_gathered = torch.gather(sin, 1, gather_indices_rope)
                
                # 应用 RoPE
                query_with_rope, key_with_rope = apply_rotary_pos_emb(query_states, key_states, cos_gathered, sin_gathered)
                
                # Padding 部分不应用 RoPE
                rope_mask = is_vl[:, None, :, None]  # [batch, 1, image_seq_len, 1]
                query_states = torch.where(rope_mask, query_with_rope, query_states)
                key_states = torch.where(rope_mask, key_with_rope, key_states)
                
            elif dinov3_len > 0:
                # TODO: 检查是否能合并进来
                # 有 dinov3 配置但没有 padding_lens（推理模式）
                cos = cos[:, dinov3_len:dinov3_len + image_seq_len]
                sin = sin[:, dinov3_len:dinov3_len + image_seq_len]
                query_states, key_states = apply_rotary_pos_emb(query_states, key_states, cos, sin)
            else:
                # dinov3_len == 0，使用原始的 cos/sin（没有 offset）
                query_states, key_states = apply_rotary_pos_emb(query_states, key_states, cos, sin)

        if past_key_values is not None:
            # sin and cos are specific to RoPE models; cache_position needed for the static cache
            cache_kwargs = {"sin": sin, "cos": cos, "cache_position": cache_position}
            key_states, value_states = past_key_values.update(key_states, value_states, self.layer_idx, cache_kwargs)

        attention_interface: Callable = eager_attention_forward
        if attention_implementation != "eager":
            attention_interface = ALL_ATTENTION_FUNCTIONS[attention_implementation]

        attn_output, attn_weights = attention_interface(
            self,
            query_states,
            key_states,
            value_states,
            attention_mask,
            dropout=0.0 if not self.training else self.attention_dropout,
            scaling=self.scaling,
            output_attentions=output_attentions,
            **kwargs,
        )

        # 📌 重要：根据是否有 dinov3 来决定 reshape 和 projection 的处理方式
        # 现在序列顺序是 [padding][dinov3][vl]
        if dinov3_qkv is not None and dinov3_len > 0:
            # 有 dinov3：attn_output 包含 [padding][dinov3][vl]
            # 需要裁剪出 [padding][vl] 部分，丢弃 dinov3 部分
            batch_size = input_shape[0]
            total_seq_len = dinov3_len + input_shape[1]  # full_seq_len = padding + dinov3 + vl
            hidden_dim = attn_output.shape[-1] if attn_output.dim() > 2 else self.config.hidden_size
            attn_output = attn_output.reshape(batch_size, total_seq_len, -1).contiguous()
            hidden_dim = attn_output.shape[-1]
            
            # ============================================================
            # 📌 向量化裁剪：使用 torch.gather 避免 for 循环
            # ============================================================
            # 目标：从 [padding][dinov3][vl] 提取 [padding][vl]
            # 即跳过 dinov3 部分
            
            device = attn_output.device
            output_seq_len = input_shape[1]  # = padding + vl
            
            # 创建位置索引 [batch, output_seq_len]
            positions = torch.arange(output_seq_len, device=device).unsqueeze(0).expand(batch_size, -1)
            
            if padding_lens is not None:
                pad_lens = padding_lens[:, None]  # [batch, 1]
            else:
                pad_lens = torch.zeros(batch_size, 1, dtype=torch.long, device=device)
            
            # 计算提取索引
            # 对于输出位置 j：
            #   - j < pad_len: 取 j (padding 部分位置不变)
            #   - j >= pad_len: 取 j + dinov3_len (跳过 dinov3，取 vl 部分)
            is_padding = positions < pad_lens
            extract_indices = torch.where(is_padding, positions, positions + dinov3_len)
            
            # 扩展索引用于 gather: [batch, output_seq_len, hidden_dim]
            gather_indices = extract_indices[:, :, None].expand(batch_size, output_seq_len, hidden_dim)
            
            # 使用 gather 提取
            attn_output = torch.gather(attn_output, 1, gather_indices)
            attn_output = self.o_proj(attn_output)
        else:
            # 没有 dinov3：attn_output 只包含 [padding][vl]
            attn_output = attn_output.reshape(*input_shape, -1).contiguous()
            attn_output = self.o_proj(attn_output)
        
        return attn_output, attn_weights


class Qwen3VLTextMLP(nn.Module):
    def __init__(self, config):
        super().__init__()
        self.config = config
        self.hidden_size = config.hidden_size
        self.intermediate_size = config.intermediate_size
        self.gate_proj = nn.Linear(self.hidden_size, self.intermediate_size, bias=False)
        self.up_proj = nn.Linear(self.hidden_size, self.intermediate_size, bias=False)
        self.down_proj = nn.Linear(self.intermediate_size, self.hidden_size, bias=False)
        self.act_fn = ACT2FN[config.hidden_act]

    def forward(self, x):
        down_proj = self.down_proj(self.act_fn(self.gate_proj(x)) * self.up_proj(x))
        return down_proj


class Qwen3VLTextDecoderLayer(GradientCheckpointingLayer):
    def __init__(self, config: Qwen3VLTextConfig, layer_idx: int):
        super().__init__()
        self.hidden_size = config.hidden_size

        self.self_attn = Qwen3VLTextAttention(config=config, layer_idx=layer_idx)

        self.mlp = Qwen3VLTextMLP(config)
        self.input_layernorm = Qwen3VLTextRMSNorm(config.hidden_size, eps=config.rms_norm_eps)
        self.post_attention_layernorm = Qwen3VLTextRMSNorm(config.hidden_size, eps=config.rms_norm_eps)

    @deprecate_kwarg("past_key_value", new_name="past_key_values", version="4.58")
    def forward(
        self,
        hidden_states: torch.Tensor,
        position_embeddings: tuple[torch.Tensor, torch.Tensor],
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_values: Optional[Cache] = None,
        use_cache: Optional[bool] = False,
        cache_position: Optional[torch.LongTensor] = None,
        output_attentions: bool = False,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple[torch.Tensor, Optional[torch.Tensor]]:
        # ── Visual Token Concat mode ──────────────────────────────────────────
        # If the caller passes `visual_tokens`, we temporarily expand hidden_states
        # to [pad][visual][vl], run the full decoder layer (attn + MLP), then
        # strip the visual prefix before returning.
        # The attention_mask and position_embeddings passed to this layer are
        # already sized for the full [pad][visual][vl] sequence; dinov3_len=0 so
        # the attention applies normal RoPE to the full hidden_states.
        visual_tokens = kwargs.pop('visual_tokens', None)  # [B, N_visual, D]
        visual_token_len = kwargs.pop('visual_token_len', 0)

        if visual_tokens is not None and visual_token_len > 0:
            B, S, D = hidden_states.shape
            device = hidden_states.device
            full_len = visual_token_len + S

            # Build [pad][visual][vl] via vectorized gather.
            # Strategy: concat [pad][vl] + [visual] along dim=1 →
            #   combined: [B, S + N_visual, D] ordered [pad][vl][visual]
            # Then reorder so that:
            #   positions 0..pad_len-1        → combined[i]              (padding)
            #   positions pad_len..pad_len+N-1 → combined[S + (i-pad_len)] (visual)
            #   positions pad_len+N..          → combined[i - N_visual]   (vl)
            combined = torch.cat([hidden_states, visual_tokens], dim=1)  # [B, S+N, D]

            positions = torch.arange(full_len, device=device).unsqueeze(0).expand(B, -1)
            padding_lens = kwargs.get('padding_lens', None)
            if padding_lens is not None:
                pad_lens = padding_lens[:, None]   # [B, 1]
            else:
                pad_lens = torch.zeros(B, 1, dtype=torch.long, device=device)

            is_padding = positions < pad_lens
            is_visual  = (positions >= pad_lens) & (positions < pad_lens + visual_token_len)

            gather_idx = torch.where(
                is_padding,
                positions,                                      # padding → identity
                torch.where(
                    is_visual,
                    S + (positions - pad_lens),                 # visual  → appended part
                    positions - visual_token_len,               # vl      → shift back
                )
            ).clamp(0, S + visual_token_len - 1)
            gather_idx_exp = gather_idx[:, :, None].expand(B, full_len, D)
            full_hidden = torch.gather(combined, 1, gather_idx_exp)
            # full_hidden: [B, full_len, D] ordered [pad][visual][vl]

            # ── Run full decoder layer on expanded hidden_states ──────────────
            residual   = full_hidden
            full_hidden = self.input_layernorm(full_hidden)
            full_hidden, self_attn_weights = self.self_attn(
                hidden_states=full_hidden,
                attention_mask=attention_mask,
                position_ids=position_ids,
                past_key_values=past_key_values,
                use_cache=use_cache,
                cache_position=cache_position,
                position_embeddings=position_embeddings,
                output_attentions=output_attentions,
                **kwargs,
            )
            full_hidden = residual + full_hidden

            residual   = full_hidden
            full_hidden = self.post_attention_layernorm(full_hidden)
            full_hidden = self.mlp(full_hidden)
            full_hidden = residual + full_hidden

            # ── Extract [pad][vl] from [pad][visual][vl] ─────────────────────
            # For output position j:
            #   j < pad_len    → take full_hidden[:, j, :]
            #   j >= pad_len   → take full_hidden[:, j + visual_token_len, :]
            positions_out  = torch.arange(S, device=device).unsqueeze(0).expand(B, -1)
            is_pad_out     = positions_out < pad_lens
            extract_idx    = torch.where(is_pad_out, positions_out,
                                         positions_out + visual_token_len)
            extract_idx_exp = extract_idx[:, :, None].expand(B, S, D)
            hidden_states  = torch.gather(full_hidden, 1, extract_idx_exp)

            outputs = (hidden_states,)
            if output_attentions:
                outputs += (self_attn_weights,)
            return outputs

        # ── Normal (non-token-concat) forward ────────────────────────────────
        residual = hidden_states
        hidden_states = self.input_layernorm(hidden_states)
        # Self Attention
        hidden_states, self_attn_weights = self.self_attn(
            hidden_states=hidden_states,
            attention_mask=attention_mask,
            position_ids=position_ids,
            past_key_values=past_key_values,
            use_cache=use_cache,
            cache_position=cache_position,
            position_embeddings=position_embeddings,
            output_attentions=output_attentions,
            **kwargs,
        )
        hidden_states = residual + hidden_states

        # Fully Connected
        residual = hidden_states
        hidden_states = self.post_attention_layernorm(hidden_states)
        hidden_states = self.mlp(hidden_states)
        hidden_states = residual + hidden_states

        outputs = (hidden_states,)
        if output_attentions:
            outputs += (self_attn_weights,)
        return outputs


@dataclass
@auto_docstring(
    custom_intro="""
    Base class for Llava outputs, with hidden states and attentions.
    """
)
class Qwen3VLModelOutputWithPast(ModelOutput):
    r"""
    past_key_values (`Cache`, *optional*, returned when `use_cache=True` is passed or when `config.use_cache=True`):
        It is a [`~cache_utils.Cache`] instance. For more details, see our [kv cache guide](https://huggingface.co/docs/transformers/en/kv_cache).

        Contains pre-computed hidden-states (key and values in the self-attention blocks) that can be used (see
        `past_key_values` input) to speed up sequential decoding.
    rope_deltas (`torch.LongTensor` of shape `(batch_size, )`, *optional*):
        The rope index difference between sequence length and multimodal rope.
    """

    last_hidden_state: Optional[torch.FloatTensor] = None
    past_key_values: Optional[Cache] = None
    hidden_states: Optional[tuple[torch.FloatTensor]] = None
    attentions: Optional[tuple[torch.FloatTensor]] = None
    rope_deltas: Optional[torch.LongTensor] = None
    attention_map_resized: Optional[torch.FloatTensor] = None
    attention_to_visual_all_layers: Optional[list[torch.FloatTensor]] = None
    attention_map_resized_all_layers: Optional[list[torch.FloatTensor]] = None
    aggregated_attention_to_visual: Optional[torch.FloatTensor] = None


@auto_docstring
class Qwen3VLPreTrainedModel(PreTrainedModel):
    config: Qwen3VLConfig
    base_model_prefix = "model"
    supports_gradient_checkpointing = True
    _no_split_modules = ["Qwen3VLTextDecoderLayer", "Qwen3VLVisionBlock"]
    _skip_keys_device_placement = "past_key_values"
    _supports_flash_attn = True
    _supports_sdpa = True

    _can_compile_fullgraph = True
    _supports_attention_backend = True
    _can_record_outputs = {
        "hidden_states": Qwen3VLTextDecoderLayer,
        "attentions": Qwen3VLTextAttention,
    }


class Qwen3VLVisionModel(Qwen3VLPreTrainedModel):
    config: Qwen3VLVisionConfig
    _no_split_modules = ["Qwen3VLVisionBlock"]

    def __init__(self, config, *inputs, **kwargs) -> None:
        super().__init__(config, *inputs, **kwargs)
        self.spatial_merge_size = config.spatial_merge_size
        self.patch_size = config.patch_size
        self.spatial_merge_unit = self.spatial_merge_size * self.spatial_merge_size

        self.patch_embed = Qwen3VLVisionPatchEmbed(
            config=config,
        )

        self.pos_embed = nn.Embedding(config.num_position_embeddings, config.hidden_size)
        self.num_grid_per_side = int(config.num_position_embeddings**0.5)

        head_dim = config.hidden_size // config.num_heads
        self.rotary_pos_emb = Qwen3VLVisionRotaryEmbedding(head_dim // 2)

        self.blocks = nn.ModuleList([Qwen3VLVisionBlock(config) for _ in range(config.depth)])
        self.merger = Qwen3VLVisionPatchMerger(
            config=config,
            use_postshuffle_norm=False,
        )

        self.deepstack_visual_indexes = config.deepstack_visual_indexes
        self.deepstack_merger_list = nn.ModuleList(
            [
                Qwen3VLVisionPatchMerger(
                    config=config,
                    use_postshuffle_norm=True,
                )
                for _ in range(len(config.deepstack_visual_indexes))
            ]
        )

        self.gradient_checkpointing = False

    def rot_pos_emb(self, grid_thw: torch.Tensor) -> torch.Tensor:
        merge_size = self.spatial_merge_size

        max_hw = int(grid_thw[:, 1:].max().item())
        freq_table = self.rotary_pos_emb(max_hw)  # (max_hw, dim // 2)
        device = freq_table.device

        total_tokens = int(torch.prod(grid_thw, dim=1).sum().item())
        pos_ids = torch.empty((total_tokens, 2), dtype=torch.long, device=device)

        offset = 0
        for num_frames, height, width in grid_thw:
            merged_h, merged_w = height // merge_size, width // merge_size

            block_rows = torch.arange(merged_h, device=device)  # block row indices
            block_cols = torch.arange(merged_w, device=device)  # block col indices
            intra_row = torch.arange(merge_size, device=device)  # intra-block row offsets
            intra_col = torch.arange(merge_size, device=device)  # intra-block col offsets

            # Compute full-resolution positions
            row_idx = block_rows[:, None, None, None] * merge_size + intra_row[None, None, :, None]
            col_idx = block_cols[None, :, None, None] * merge_size + intra_col[None, None, None, :]

            row_idx = row_idx.expand(merged_h, merged_w, merge_size, merge_size).reshape(-1)
            col_idx = col_idx.expand(merged_h, merged_w, merge_size, merge_size).reshape(-1)

            coords = torch.stack((row_idx, col_idx), dim=-1)

            if num_frames > 1:
                coords = coords.repeat(num_frames, 1)

            num_tokens = coords.shape[0]
            pos_ids[offset : offset + num_tokens] = coords
            offset += num_tokens

        embeddings = freq_table[pos_ids]  # lookup rotary embeddings
        embeddings = embeddings.flatten(1)
        return embeddings

    def fast_pos_embed_interpolate(self, grid_thw):
        grid_ts, grid_hs, grid_ws = grid_thw[:, 0], grid_thw[:, 1], grid_thw[:, 2]

        idx_list = [[] for _ in range(4)]
        weight_list = [[] for _ in range(4)]

        for t, h, w in zip(grid_ts, grid_hs, grid_ws):
            h_idxs = torch.linspace(0, self.num_grid_per_side - 1, h)
            w_idxs = torch.linspace(0, self.num_grid_per_side - 1, w)

            h_idxs_floor = h_idxs.int()
            w_idxs_floor = w_idxs.int()
            h_idxs_ceil = (h_idxs.int() + 1).clip(max=self.num_grid_per_side - 1)
            w_idxs_ceil = (w_idxs.int() + 1).clip(max=self.num_grid_per_side - 1)

            dh = h_idxs - h_idxs_floor
            dw = w_idxs - w_idxs_floor

            base_h = h_idxs_floor * self.num_grid_per_side
            base_h_ceil = h_idxs_ceil * self.num_grid_per_side

            indices = [
                (base_h[None].T + w_idxs_floor[None]).flatten(),
                (base_h[None].T + w_idxs_ceil[None]).flatten(),
                (base_h_ceil[None].T + w_idxs_floor[None]).flatten(),
                (base_h_ceil[None].T + w_idxs_ceil[None]).flatten(),
            ]

            weights = [
                ((1 - dh)[None].T * (1 - dw)[None]).flatten(),
                ((1 - dh)[None].T * dw[None]).flatten(),
                (dh[None].T * (1 - dw)[None]).flatten(),
                (dh[None].T * dw[None]).flatten(),
            ]

            for i in range(4):
                idx_list[i].extend(indices[i].tolist())
                weight_list[i].extend(weights[i].tolist())

        idx_tensor = torch.tensor(idx_list, dtype=torch.long, device=self.pos_embed.weight.device)
        weight_tensor = torch.tensor(
            weight_list, dtype=self.pos_embed.weight.dtype, device=self.pos_embed.weight.device
        )
        pos_embeds = self.pos_embed(idx_tensor) * weight_tensor[:, :, None]
        patch_pos_embeds = pos_embeds[0] + pos_embeds[1] + pos_embeds[2] + pos_embeds[3]

        patch_pos_embeds = patch_pos_embeds.split([h * w for h, w in zip(grid_hs, grid_ws)])

        patch_pos_embeds_permute = []
        merge_size = self.config.spatial_merge_size
        for pos_embed, t, h, w in zip(patch_pos_embeds, grid_ts, grid_hs, grid_ws):
            pos_embed = pos_embed.repeat(t, 1)
            pos_embed = (
                pos_embed.view(t, h // merge_size, merge_size, w // merge_size, merge_size, -1)
                .permute(0, 1, 3, 2, 4, 5)
                .flatten(0, 4)
            )
            patch_pos_embeds_permute.append(pos_embed)
        patch_pos_embeds = torch.cat(patch_pos_embeds_permute)
        return patch_pos_embeds

    def forward(self, hidden_states: torch.Tensor, grid_thw: torch.Tensor, **kwargs) -> torch.Tensor:
        """
        Args:
            hidden_states (`torch.Tensor` of shape `(seq_len, hidden_size)`):
                The final hidden states of the model.
            grid_thw (`torch.Tensor` of shape `(num_images_or_videos, 3)`):
                The temporal, height and width of feature shape of each image in LLM.

        Returns:
            `torch.Tensor`: hidden_states.
        """
        hidden_states = self.patch_embed(hidden_states)

        pos_embeds = self.fast_pos_embed_interpolate(grid_thw)
        hidden_states = hidden_states + pos_embeds

        rotary_pos_emb = self.rot_pos_emb(grid_thw)

        seq_len, _ = hidden_states.size()
        hidden_states = hidden_states.reshape(seq_len, -1)
        rotary_pos_emb = rotary_pos_emb.reshape(seq_len, -1)
        emb = torch.cat((rotary_pos_emb, rotary_pos_emb), dim=-1)
        position_embeddings = (emb.cos(), emb.sin())

        cu_seqlens = torch.repeat_interleave(grid_thw[:, 1] * grid_thw[:, 2], grid_thw[:, 0]).cumsum(
            dim=0,
            # Select dtype based on the following factors:
            #  - FA2 requires that cu_seqlens_q must have dtype int32
            #  - torch.onnx.export requires that cu_seqlens_q must have same dtype as grid_thw
            # See https://github.com/huggingface/transformers/pull/34852 for more information
            dtype=grid_thw.dtype if torch.jit.is_tracing() else torch.int32,
        )
        cu_seqlens = F.pad(cu_seqlens, (1, 0), value=0)

        # Pop per-layer QKV collectors for SigLIP MOT (dict: {vit_layer_idx -> {}})
        siglip_qkv_collectors = kwargs.pop('siglip_qkv_collectors', None)
        # Pop per-layer token collectors for Visual Token Concat (dict: {vit_layer_idx -> {}})
        visual_token_collectors = kwargs.pop('visual_token_collectors', None)

        deepstack_feature_lists = []
        for layer_num, blk in enumerate(self.blocks):
            _collector = (siglip_qkv_collectors.get(layer_num)
                          if siglip_qkv_collectors is not None else None)
            hidden_states = blk(
                hidden_states,
                cu_seqlens=cu_seqlens,
                position_embeddings=position_embeddings,
                siglip_qkv_collector=_collector,
                **kwargs,
            )
            # Capture block output tokens for Visual Token Concat mode
            if visual_token_collectors is not None and layer_num in visual_token_collectors:
                visual_token_collectors[layer_num] = {
                    'hidden': hidden_states,   # [total_patches, hidden_dim]
                    'cu_seqlens': cu_seqlens,  # [n_imgs+1]
                }
            if layer_num in self.deepstack_visual_indexes:
                deepstack_feature = self.deepstack_merger_list[self.deepstack_visual_indexes.index(layer_num)](
                    hidden_states
                )
                deepstack_feature_lists.append(deepstack_feature)
        hidden_states = self.merger(hidden_states)

        return hidden_states, deepstack_feature_lists


@auto_docstring(
    custom_intro=(
        "Text part of Qwen3VL, "
        "not a pure text-only model, as DeepStack integrates visual features into the early hidden states."
    )
)
class Qwen3VLTextModel(Qwen3VLPreTrainedModel):
    config: Qwen3VLTextConfig
    _no_split_modules = ["Qwen3VLTextDecoderLayer"]

    def __init__(self, config: Qwen3VLTextConfig):
        super().__init__(config)
        self.padding_idx = config.pad_token_id
        self.vocab_size = config.vocab_size

        self.embed_tokens = nn.Embedding(config.vocab_size, config.hidden_size, self.padding_idx)
        self.layers = nn.ModuleList(
            [Qwen3VLTextDecoderLayer(config, layer_idx) for layer_idx in range(config.num_hidden_layers)]
        )
        self.norm = Qwen3VLTextRMSNorm(config.hidden_size, eps=config.rms_norm_eps)
        self.rotary_emb = Qwen3VLTextRotaryEmbedding(config=config)
        self.gradient_checkpointing = False

        # Initialize weights and apply final processing
        self.post_init()

    @check_model_inputs
    @auto_docstring
    def forward(
        self,
        input_ids: Optional[torch.LongTensor] = None,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_values: Optional[Cache] = None,
        inputs_embeds: Optional[torch.FloatTensor] = None,
        use_cache: Optional[bool] = None,
        output_hidden_states: Optional[bool] = None,
        cache_position: Optional[torch.LongTensor] = None,
        # args for deepstack
        visual_pos_masks: Optional[torch.Tensor] = None,
        deepstack_visual_embeds: Optional[list[torch.Tensor]] = None,
        # args for dinov3
        dinov3_qkv_states: Optional[dict] = None,
        dinov3_qwen_mapping: Optional[dict] = None,
        dinov3_len: int = 0,
        # args for visual token concat (ablation vs MOT)
        visual_token_states: Optional[dict] = None,  # {qwen_layer: Tensor[B, N, D]}
        # args for token pruning
        pruning_mode: str = 'none',
        pruning_ref_layer: Optional[int] = None,
        pruning_ratio: float = 0.0,
        action_length: int = 0,
        prefix_tokens_lens: Optional[torch.Tensor] = None,
        instruction_ranges: Optional[torch.Tensor] = None,
        dinov3_num_register_tokens: int = 4,
        expert_num_prefix_tokens: Optional[int] = None,
        expert_patch_grid_contract: str = "strict_square",
        expert_token_order: str = "importance",
        vl_position_contract: str = "historical_expert_offset_all_layers",
        pruning_attention_index_contract: str = "historical_base_indices",
        pruning_layer_index_base: str = "zero",
        action_task_attention_contract: str = "historical_joint_mean",
        attention_collection_mask_contract: str = "historical_sdpa_eager_mismatch",
        vla_attention_mask_contract: str = "historical_causal",
        expert_private_to_action: int = 0,
        # args for multi-layer attention aggregation (pruning)
        pruning_attn_aggregation: str = 'none',   # none | mean_layers | vote | intersection | action_task_mean
        pruning_attn_aggregation_layer_start: int = 3,
        pruning_attn_aggregation_layer_end: int = 10,
        pruning_attn_aggregation_vote_ratio: float = 0.6,
        pruning_vote_contract: str = "historical_floor_global_fallback",
        # args for efficient dinov3 mode (called inside model after pruning)
        dinov3_model: Optional[nn.Module] = None,
        dinov3_aligner: Optional[nn.Module] = None,
        dinov3_pixel_values: Optional[torch.Tensor] = None,
        dinov3_efficient: bool = False,
        dinov3_qkv_after_rope: bool = True,
        train_dinov3_full_finetune: bool = False,
        # args for action-image attention restriction
        action_attn_mode: str = 'none',   # none | pre_image | non_image | roi_image
        action_img_attn_start_layer: int = -1,
        action_attn_roi_layer_start: int = 3,
        action_attn_roi_layer_end: int = 10,
        action_attn_roi_ratio: float = 0.5,
        **kwargs: Unpack[FlashAttentionKwargs],
    ) -> Union[tuple, BaseModelOutputWithPast]:
        r"""
        visual_pos_masks (`torch.Tensor` of shape `(batch_size, seqlen)`, *optional*):
            The mask of the visual positions.
        deepstack_visual_embeds (`list[torch.Tensor]`, *optional*):
            The deepstack visual embeddings. The shape is (num_layers, visual_seqlen, embed_dim).
            The feature is extracted from the different visual encoder layers, and fed to the decoder
            hidden states. It's from the paper DeepStack(https://arxiv.org/abs/2406.04334).
        dinov3_qkv_states (`dict`, *optional*):
            Pre-computed Q/K/V states from DINOv3 encoder for cross-attention or token pruning.
        dinov3_qwen_mapping (`dict`, *optional*):
            Mapping from Qwen decoder layer indices to DINOv3 layer indices (e.g. {20: 0, 21: 2, ...}).
        dinov3_len (`int`, *optional*, defaults to 0):
            Sequence length of DINOv3 tokens (CLS + register + patch tokens).
        visual_token_states (`dict`, *optional*):
            Per-Qwen-layer expert token states used by the visual-token-concat ablation.
        pruning_mode (`str`, *optional*, defaults to `"none"`):
            Token pruning mode: `"none"`, `"qwen_action"`, or `"qwen_task"`.
        pruning_ref_layer (`int`, *optional*):
            Decoder layer index used as reference for attention-based DINOv3 token pruning.
        pruning_ratio (`float`, *optional*, defaults to 0.0):
            Ratio of DINOv3 patch tokens to prune (0-1) or number of tokens to keep if > 1.
        action_length (`int`, *optional*, defaults to 0):
            Number of action tokens (used for qwen_action pruning and attention extraction).
        prefix_tokens_lens (`torch.Tensor`, *optional*):
            Per-sample prefix lengths for variable-length sequences.
        instruction_ranges (`torch.Tensor`, *optional*):
            Per-sample instruction token ranges for qwen_task pruning.
        dinov3_num_register_tokens (`int`, *optional*, defaults to 4):
            Number of DINOv3 register tokens (excluding CLS). Used only as a compatibility fallback when
            `expert_num_prefix_tokens` is not provided.
        expert_num_prefix_tokens (`int`, *optional*):
            Number of non-patch tokens at the start of each expert QKV sequence. DINOv3 uses CLS plus register
            tokens; Qwen-ViT/SigLIP QKV uses zero prefix tokens.
        expert_patch_grid_contract (`str`, *optional*, defaults to `"strict_square"`):
            Spatial-grid interpretation for expert patch tokens. `"legacy_floor_square"` reproduces the
            published SigLIP path that treated one real patch as a prefix and ranked only a 15x15 grid.
        expert_token_order (`str`, *optional*, defaults to `"importance"`):
            Order of retained expert patch tokens after top-K selection. `"importance"` reproduces the
            historical score-ranked sequence; `"spatial"` restores ascending raster order.
        vl_position_contract (`str`, *optional*, defaults to `"historical_expert_offset_all_layers"`):
            Whether non-coupled Qwen layers inherit the expert-length RoPE offset. `"native_unmapped_layers"`
            keeps original Qwen position semantics on layers without expert QKV. `"preserve_qwen_mrope"`
            additionally preserves the original Qwen MRoPE coordinates on coupled layers.
        pruning_attention_index_contract (`str`, *optional*, defaults to `"historical_base_indices"`):
            Index space used to gather pruning guidance from attention maps. `"expanded_sequence"` maps
            Qwen token indices into `[padding][expert][VL]` on coupled layers.
        pruning_layer_index_base (`str`, *optional*, defaults to `"zero"`):
            Index base used by pruning reference and aggregation layer arguments.
        action_task_attention_contract (`str`, *optional*, defaults to `"historical_joint_mean"`):
            `"historical_joint_mean"` reproduces the previous implementation by averaging task-to-visual
            and action-to-visual attention in each selected layer. `"action_only"` is the true action-only
            ablation. `"joint_mean"` and `"historical_action_only"` remain compatibility aliases.
        attention_collection_mask_contract (`str`, *optional*, defaults to `"historical_sdpa_eager_mismatch"`):
            Mask semantics used when an SDPA layer is temporarily switched to eager attention to expose
            attention weights. The historical mode reproduces the old mismatch; `"corrected_causal"`
            materializes an eager additive causal mask without changing token visibility.
        vla_attention_mask_contract (`str`, *optional*, defaults to `"historical_causal"`):
            Visibility contract for VLA tokens. `"historical_causal"` keeps standard decoder causality;
            `"prompt_causal_action_bidirectional"` keeps prompt rows causal while allowing the final
            `action_length` query/key block to attend bidirectionally.
        expert_private_to_action (`int`, *optional*, defaults to 0):
            When 1, expert (DINOv3/SigLIP) key/value columns become private to the trailing
            `action_length` action query rows: VL non-action query rows can no longer attend
            expert key columns on expert-injection layers. Mask-only change; 0 keeps the
            released behavior bit-identical.
        pruning_attn_aggregation (`str`, *optional*, defaults to `"none"`):
            Multi-layer attention aggregation strategy for pruning: `"none"` (single ref layer),
            `"mean_layers"` (average across layers), `"vote"` (top-k vote across layers),
            `"action_task_mean"` (average of action and task attention).
        pruning_attn_aggregation_layer_start (`int`, *optional*, defaults to 3):
            Start layer (inclusive) for multi-layer attention aggregation.
        pruning_attn_aggregation_layer_end (`int`, *optional*, defaults to 10):
            End layer (inclusive) for multi-layer attention aggregation.
        pruning_attn_aggregation_vote_ratio (`float`, *optional*, defaults to 0.6):
            For `"vote"` aggregation: minimum ratio of layers a token must appear in to be kept.
        pruning_vote_contract (`str`, *optional*, defaults to `"historical_floor_global_fallback"`):
            Threshold and empty-set semantics for vote/intersection aggregation. The historical contract uses
            floor rounding and the original batch-global fallback; `"strict_ceil_fail_closed"` uses ceil rounding
            and rejects empty selections.
        dinov3_model (`nn.Module`, *optional*):
            DINOv3 model invoked inside the text model by the efficient expert path.
        dinov3_aligner (`nn.Module`, *optional*):
            Module that aligns DINOv3 query, key, and value tensors to Qwen attention geometry.
        dinov3_pixel_values (`torch.Tensor`, *optional*):
            DINOv3 image tensor used by the efficient expert path.
        dinov3_efficient (`bool`, *optional*, defaults to `False`):
            Whether to execute DINOv3 lazily after pruning guidance is available.
        dinov3_qkv_after_rope (`bool`, *optional*, defaults to `True`):
            Whether efficient-mode expert query and key tensors are collected after DINOv3 RoPE.
        train_dinov3_full_finetune (`bool`, *optional*, defaults to `False`):
            Whether the lazily executed DINOv3 model participates in full fine-tuning.
        action_attn_mode (`str`, *optional*, defaults to `"none"`):
            Optional action-row visibility restriction used by attention ablations.
        action_img_attn_start_layer (`int`, *optional*, defaults to -1):
            First Qwen layer on which the action attention restriction is applied.
        action_attn_roi_layer_start (`int`, *optional*, defaults to 3):
            First layer contributing action-to-image attention to the ROI restriction.
        action_attn_roi_layer_end (`int`, *optional*, defaults to 10):
            Last layer contributing action-to-image attention to the ROI restriction.
        action_attn_roi_ratio (`float`, *optional*, defaults to 0.5):
            Fraction of image tokens retained by the ROI restriction.
        """
        if (input_ids is None) ^ (inputs_embeds is not None):
            raise ValueError("You must specify exactly one of input_ids or inputs_embeds")

        # torch.jit.trace() doesn't support cache objects in the output
        if use_cache and past_key_values is None and not torch.jit.is_tracing():
            past_key_values = DynamicCache(config=self.config)

        if inputs_embeds is None:
            inputs_embeds = self.embed_tokens(input_ids)
        output_hidden_states = (
            self.config.output_hidden_states
            if output_hidden_states is None
            else bool(output_hidden_states)
        )

        if cache_position is None:
            past_seen_tokens = past_key_values.get_seq_length() if past_key_values is not None else 0
            cache_position = torch.arange(
                past_seen_tokens, past_seen_tokens + inputs_embeds.shape[1], device=inputs_embeds.device
            )

        # the hard coded `3` is for temporal, height and width.
        if position_ids is None:
            position_ids = cache_position.view(1, 1, -1).expand(3, inputs_embeds.shape[0], -1)
        elif position_ids.ndim == 2:
            position_ids = position_ids[None, ...].expand(3, position_ids.shape[0], -1)

        # here
        if position_ids.ndim == 3 and position_ids.shape[0] == 4:
            text_position_ids = position_ids[0]
            position_ids = position_ids[1:]
        else:
            text_position_ids = position_ids[0]

        collect_attention_maps = kwargs.pop('collect_attention_maps', False)
        if expert_num_prefix_tokens is None:
            expert_num_prefix_tokens = 1 + int(dinov3_num_register_tokens)
        expert_num_prefix_tokens = int(expert_num_prefix_tokens)
        if expert_num_prefix_tokens < 0:
            raise ValueError(
                f"expert_num_prefix_tokens must be non-negative; got {expert_num_prefix_tokens}."
            )
        if expert_patch_grid_contract not in {"strict_square", "legacy_floor_square"}:
            raise ValueError(
                "expert_patch_grid_contract must be 'strict_square' or 'legacy_floor_square'; "
                f"got {expert_patch_grid_contract!r}."
            )
        if pruning_vote_contract not in PRUNING_VOTE_CONTRACTS:
            raise ValueError(
                "pruning_vote_contract must be one of "
                f"{sorted(PRUNING_VOTE_CONTRACTS)}; got {pruning_vote_contract!r}."
            )
        if expert_token_order not in {"importance", "spatial"}:
            raise ValueError(
                "expert_token_order must be 'importance' or 'spatial'; "
                f"got {expert_token_order!r}."
            )
        if vl_position_contract not in {
            "historical_expert_offset_all_layers",
            "native_unmapped_layers",
            "preserve_qwen_mrope",
        }:
            raise ValueError(
                "vl_position_contract must be 'historical_expert_offset_all_layers', "
                "'native_unmapped_layers', or 'preserve_qwen_mrope'; "
                f"got {vl_position_contract!r}."
            )
        if pruning_layer_index_base not in {"zero", "one"}:
            raise ValueError(
                "pruning_layer_index_base must be 'zero' or 'one'; "
                f"got {pruning_layer_index_base!r}."
            )
        if pruning_attention_index_contract not in {
            "historical_base_indices",
            "expanded_sequence",
        }:
            raise ValueError(
                "pruning_attention_index_contract must be 'historical_base_indices' or "
                f"'expanded_sequence'; got {pruning_attention_index_contract!r}."
            )
        if action_task_attention_contract not in {
            "historical_joint_mean",
            "joint_mean",
            "action_only",
            "historical_action_only",
        }:
            raise ValueError(
                "action_task_attention_contract must be 'historical_joint_mean', 'joint_mean', "
                "'action_only', or 'historical_action_only'; "
                f"got {action_task_attention_contract!r}."
            )
        if attention_collection_mask_contract not in {
            "historical_sdpa_eager_mismatch",
            "corrected_causal",
        }:
            raise ValueError(
                "attention_collection_mask_contract must be "
                "'historical_sdpa_eager_mismatch' or 'corrected_causal'; "
                f"got {attention_collection_mask_contract!r}."
            )
        if vla_attention_mask_contract not in {
            "historical_causal",
            "prompt_causal_action_bidirectional",
        }:
            raise ValueError(
                "vla_attention_mask_contract must be 'historical_causal' or "
                "'prompt_causal_action_bidirectional'; "
                f"got {vla_attention_mask_contract!r}."
            )
        if expert_private_to_action not in {0, 1}:
            raise ValueError(
                f"expert_private_to_action must be 0 or 1; got {expert_private_to_action!r}."
            )
        if action_attn_mode not in {"none", "pre_image", "non_image", "roi_image"}:
            raise ValueError(
                "action_attn_mode must be 'none', 'pre_image', 'non_image', or 'roi_image'; "
                f"got {action_attn_mode!r}."
            )
        if action_attn_mode != "none":
            if action_img_attn_start_layer < 0:
                raise ValueError(
                    "action_img_attn_start_layer must be non-negative when action_attn_mode is enabled."
                )
            if action_length <= 0:
                raise ValueError("action_length must be positive when action_attn_mode is enabled.")
            if visual_pos_masks is None:
                raise ValueError(
                    "visual_pos_masks is required when action_attn_mode is enabled; "
                    "otherwise image-key positions cannot be resolved."
                )
            if action_attn_mode == "roi_image":
                if action_attn_roi_layer_start < 0 or action_attn_roi_layer_end < action_attn_roi_layer_start:
                    raise ValueError(
                        "roi_image requires 0 <= action_attn_roi_layer_start <= action_attn_roi_layer_end."
                    )
                if action_attn_roi_layer_end >= action_img_attn_start_layer:
                    raise ValueError(
                        "roi_image attention collection must finish before action restriction starts; "
                        f"got ROI end layer {action_attn_roi_layer_end} and restriction start layer "
                        f"{action_img_attn_start_layer}."
                    )
                if not 0.0 < action_attn_roi_ratio <= 1.0:
                    raise ValueError(
                        f"action_attn_roi_ratio must be in (0, 1]; got {action_attn_roi_ratio}."
                    )

        # ========== Token Pruning 相关变量初始化 ==========
        # ⚠️ 重要：必须在创建 causal_mask 之前计算剪枝后的 dinov3_len
        # 这样 causal_mask 和 position embeddings 从一开始就使用正确的尺寸
        is_qwen_pruning_mode = (pruning_mode in ['qwen_action', 'qwen_task'] and pruning_ratio > 0)
        # 在 efficient 模式下，即使 dinov3_qkv_states 为 None，也需要进行 attention aggregation
        need_qwen_pruning = (is_qwen_pruning_mode and 
                              ((dinov3_qkv_states is not None and len(dinov3_qkv_states) > 0) or 
                               (dinov3_efficient and dinov3_model is not None)))
        token_keep_indices_for_dinov3 = None  # 用于存储剪枝后要保留的 token 索引
        pruning_applied = False  # 标记是否已应用剪枝
        attention_to_visual_all_layers = [] if collect_attention_maps else None
        attention_map_resized_all_layers = [] if collect_attention_maps else None
        latest_attention_map_resized = None
        # 聚合后的 attention（Qwen visual 分辨率），供外部可视化直接使用，避免重复计算
        latest_aggregated_attention_to_visual = None
        # efficient 模式下，记录是否已经调用了 DinoV3
        dinov3_called_in_efficient_mode = False
        unpruned_dinov3_len = int(dinov3_len)

        # ========== 多层聚合相关变量 ==========
        # 聚合模式下需要收集多层 attention 再统一做剪枝，而不是到 ref_layer 立刻剪枝
        use_aggregation = need_qwen_pruning and _uses_pruning_attention_aggregation(
            pruning_attn_aggregation
        )
        # 已解析的聚合层范围（合法化后的正整数索引）
        num_layers = len(self.layers)
        agg_layer_start = 0
        agg_layer_end = 0
        if use_aggregation:
            agg_layer_start = _resolve_pruning_layer_index(
                pruning_attn_aggregation_layer_start,
                num_layers=num_layers,
                index_base=pruning_layer_index_base,
                label="pruning_attn_aggregation_layer_start",
            )
            agg_layer_end = _resolve_pruning_layer_index(
                pruning_attn_aggregation_layer_end,
                num_layers=num_layers,
                index_base=pruning_layer_index_base,
                label="pruning_attn_aggregation_layer_end",
            )
            if agg_layer_start > agg_layer_end:
                raise ValueError(
                    "pruning attention aggregation start must not exceed end; "
                    f"got code layers {agg_layer_start}>{agg_layer_end}."
                )
        # 按层缓存 attention_to_visual，供聚合使用：List[Optional[Tensor [batch, num_visual]]]
        _agg_attn_cache: list = []  # 仅在 use_aggregation=True 时填充

        actual_pruning_ref_layer = None
        if need_qwen_pruning and pruning_ref_layer is not None:
            actual_pruning_ref_layer = _resolve_pruning_layer_index(
                pruning_ref_layer,
                num_layers=num_layers,
                index_base=pruning_layer_index_base,
                label="pruning_ref_layer",
            )

        if need_qwen_pruning:
            pruning_completion_layer = (
                agg_layer_end if use_aggregation else actual_pruning_ref_layer
            )
            if pruning_completion_layer is None:
                raise ValueError("Qwen-guided pruning requires a valid pruning completion layer.")
            expert_injection_layers = (
                dinov3_qkv_states.keys()
                if dinov3_qkv_states
                else (dinov3_qwen_mapping or {}).keys()
            )
            _validate_pruning_before_expert_injection(
                pruning_completion_layer=pruning_completion_layer,
                expert_injection_layers=expert_injection_layers,
            )
        
        # ========== 关键优化：提前计算剪枝后的 dinov3_len ==========
        # 对于 qwen_* 剪枝模式，虽然需要运行到 ref_layer 才能获取注意力，
        # 但我们可以提前根据 pruning_ratio 计算剪枝后的长度
        # 这样 position embeddings、causal mask 等从一开始就使用正确的长度
        if need_qwen_pruning and actual_pruning_ref_layer is not None and dinov3_len > 0:
            # 计算可剪枝的 patch tokens 数量
            num_patch_tokens = _expert_patch_token_count(
                dinov3_len,
                expert_num_prefix_tokens,
                "DINOv3/SigLIP expert",
            )
            
            num_tokens_to_keep = _pruned_patch_token_count(num_patch_tokens, pruning_ratio)
            
            # 更新 dinov3_len 为剪枝后的长度
            # 注意：这里只更新长度；实际剪枝在收集/聚合完成的那一层执行
            #（单一 ref_layer 模式 = ref_layer；聚合模式 = agg_layer_end）
            dinov3_len = num_tokens_to_keep + expert_num_prefix_tokens
        
        # 创建两种 causal_mask：
        # 1. causal_mask_normal: 用于不使用 dinov3 的层（只有 image 部分）
        # 2. causal_mask_with_dinov3: 用于使用 dinov3 的层（dinov3 + image）

        # Fail-closed：bidirectional / expert_private 两个 mask builder 在 None/2D 输入下
        # 返回 bool mask（sdpa 下语义正确；eager 下 create_causal_mask 恒返回 4D float，走不到）。
        # flash_attention_2 的 unpad 路径不支持 4D bool mask，会以费解的 IndexError 崩溃，
        # 这里提前给出可读报错（2026-08-19 复审新增）。
        if self.config._attn_implementation == "flash_attention_2" and (
            vla_attention_mask_contract == "prompt_causal_action_bidirectional"
            or expert_private_to_action
        ):
            raise ValueError(
                "flash_attention_2 does not support the 4D bool masks produced by "
                "vla_attention_mask_contract='prompt_causal_action_bidirectional' or "
                "expert_private_to_action=1; use sdpa (default) or eager."
            )

        # 1. 正常层的 causal_mask（只有 image 部分）
        # [4, 1, 279, 279]
        causal_mask_normal = create_causal_mask(
            config=self.config,
            input_embeds=inputs_embeds,
            attention_mask=attention_mask, # [4, 279]
            cache_position=cache_position,  # [0 -- 278]
            past_key_values=past_key_values,
            position_ids=text_position_ids,  # position_ids[0] --> 目前三个一样
        )
        if vla_attention_mask_contract == "prompt_causal_action_bidirectional":
            causal_mask_normal = _enable_bidirectional_action_attention(
                causal_mask_normal,
                batch_size=inputs_embeds.shape[0],
                sequence_length=inputs_embeds.shape[1],
                action_length=action_length,
                dtype=inputs_embeds.dtype,
                device=inputs_embeds.device,
            )
        elif action_attn_mode != "none":
            causal_mask_normal = _materialize_causal_attention_mask(
                causal_mask_normal,
                batch_size=inputs_embeds.shape[0],
                sequence_length=inputs_embeds.shape[1],
                dtype=inputs_embeds.dtype,
                device=inputs_embeds.device,
            )
        
        # 2. dinov3 层的 causal_mask（dinov3 + image）
        # [4, 1, 860, 860], 860 = 279 + 581
        # 注意：对于 qwen_* 剪枝模式，dinov3_len 已经是剪枝后的长度
        # 因此这里创建的 mask 尺寸从一开始就是正确的，不需要后续重新创建
        causal_mask_with_dinov3 = None
        padding_lens = None  # 保存 padding 长度，传递给 Attention 层
        if dinov3_len > 0:
            # 扩展 attention_mask: [padding][dinov3][valid tokens]
            expanded_attention_mask = None
            if attention_mask is not None and attention_mask.ndim == 2:
                batch_size = attention_mask.shape[0]
                seq_len = attention_mask.shape[1]
                device = attention_mask.device
                
                # ============================================================
                # 📌 向量化计算 padding_lens
                # ============================================================
                # 找到每个样本第一个非零元素的位置（即 padding 结束的位置）
                # 对于 left padding: [0, 0, 1, 1, 1] -> padding_len = 2
                
                # 方法：使用 argmax 找到第一个 1 的位置
                # 如果全是 0，argmax 返回 0，但我们需要返回 seq_len
                # 如果全是 1，argmax 返回 0，这是正确的（没有 padding）
                
                # 创建一个辅助张量：在每行末尾添加一个 1，确保 argmax 总能找到
                has_valid = attention_mask.any(dim=1)  # [batch] 是否有有效 token
                
                # 使用 argmax 找到第一个 1 的位置
                # 注意：如果全是 0，argmax 会返回 0，需要特殊处理
                padding_lens = attention_mask.argmax(dim=1)  # [batch]
                
                # 如果某行全是 0（没有有效 token），设置 padding_lens 为 seq_len
                padding_lens = torch.where(has_valid, padding_lens, torch.full_like(padding_lens, seq_len))

                # Fail-closed（2026-08-19 复审新增）：argmax 求 padding_lens、以及下方
                # expanded mask 的拼接技巧（[pad][vl][dinov3] 与 [pad][dinov3][vl] 值等价）
                # 都假设左 padding——每行 mask 必须形如 0*1*（无 1→0 跳变）。
                # 右 padding / 中间 padding 会静默错 mask，直接拒绝。
                if bool(((attention_mask[:, 1:].long() - attention_mask[:, :-1].long()) < 0).any()):
                    raise ValueError(
                        "attention_mask must be left-padded (each row of form 0*1*); "
                        "right/interior padding breaks padding_lens inference and the "
                        "expanded-mask concat."
                    )
                
                # ============================================================
                # 📌 向量化构建 expanded_attention_mask
                # ============================================================
                # 目标：从 [padding][vl] 变为 [padding][dinov3][vl]
                # 策略：先拼接 dinov3_mask 到末尾，然后用 gather 重排
                
                full_seq_len = dinov3_len + seq_len
                
                # dinov3 部分全是 1（有效）
                dinov3_mask = torch.ones(batch_size, dinov3_len, dtype=attention_mask.dtype, device=device)
                
                # 拼接为 [padding][vl][dinov3] == [padding][dinov3][vl]
                # vl和dinov3部分都是1, 所以可以这样实现
                mask_concat = torch.cat([attention_mask, dinov3_mask], dim=1)  # [batch, full_seq_len]
                expanded_attention_mask = mask_concat

                # # 构建重排索引（与 QKV 重排相同的逻辑）
                # positions = torch.arange(full_seq_len, device=device).unsqueeze(0).expand(batch_size, -1)
                # pad_lens = padding_lens[:, None]  # [batch, 1]
                
                # is_padding = positions < pad_lens
                # is_dinov3 = (positions >= pad_lens) & (positions < pad_lens + dinov3_len)
                # is_vl = positions >= pad_lens + dinov3_len
                
                # # 计算重排索引
                # reorder_indices = torch.zeros(batch_size, full_seq_len, dtype=torch.long, device=device)
                # reorder_indices = torch.where(is_padding, positions, reorder_indices)
                # reorder_indices = torch.where(is_dinov3, seq_len + (positions - pad_lens), reorder_indices)
                # reorder_indices = torch.where(is_vl, positions - dinov3_len, reorder_indices)
                
                # # 使用 gather 重排
                # expanded_attention_mask = torch.gather(mask_concat, 1, reorder_indices)
            
            # 创建 dummy input 用于生成 causal_mask
            full_seq_len = dinov3_len + inputs_embeds.shape[1]
            dummy_input = inputs_embeds.new_zeros(
                inputs_embeds.shape[0], full_seq_len, inputs_embeds.shape[-1]
            )
            
            # 创建 full_cache_position
            if cache_position is not None:
                full_cache_position = torch.arange(
                    cache_position[0], cache_position[0] + full_seq_len,
                    device=cache_position.device
                )
            else:
                full_cache_position = torch.arange(full_seq_len, device=inputs_embeds.device)
            
            # 创建 full_position_ids
            full_text_position_ids = torch.arange(full_seq_len, device=text_position_ids.device)
            full_text_position_ids = full_text_position_ids.unsqueeze(0).expand(text_position_ids.shape[0], -1)
            
            causal_mask_with_dinov3 = create_causal_mask(
                config=self.config,
                input_embeds=dummy_input,
                attention_mask=expanded_attention_mask,
                cache_position=full_cache_position,
                past_key_values=None,  # 不使用 cache，因为这是完整序列
                position_ids=full_text_position_ids,
            )
            if vla_attention_mask_contract == "prompt_causal_action_bidirectional":
                causal_mask_with_dinov3 = _enable_bidirectional_action_attention(
                    causal_mask_with_dinov3,
                    batch_size=inputs_embeds.shape[0],
                    sequence_length=full_seq_len,
                    action_length=action_length,
                    dtype=inputs_embeds.dtype,
                    device=inputs_embeds.device,
                )
            elif action_attn_mode != "none":
                causal_mask_with_dinov3 = _materialize_causal_attention_mask(
                    causal_mask_with_dinov3,
                    batch_size=inputs_embeds.shape[0],
                    sequence_length=full_seq_len,
                    dtype=inputs_embeds.dtype,
                    device=inputs_embeds.device,
                )
            if expert_private_to_action:
                # 方案A（action-private DINO，mask-only）：VL 非 action query 行
                # 不再可读 expert K/V 列；仅末尾 action_length 个 action 行保留可读性。
                causal_mask_with_dinov3 = _restrict_expert_kv_to_action_rows(
                    causal_mask_with_dinov3,
                    batch_size=inputs_embeds.shape[0],
                    sequence_length=full_seq_len,
                    expert_len=dinov3_len,
                    action_length=action_length,
                    padding_lens=padding_lens,
                    dtype=inputs_embeds.dtype,
                    device=inputs_embeds.device,
                )

        hidden_states = inputs_embeds

        # ─────────────────────────────────────────────────────────────────────
        # Action Attention Restriction
        # Three modes (controlled by action_attn_mode):
        #   pre_image  – action Q attends only to image tokens onward
        #   non_image  – action Q attends only to image tokens + own action tokens
        #   roi_image  – like non_image but restricted to ROI image tokens selected
        #                by aggregating early-layer attention maps (built in the loop)
        # All modes activate from `action_img_attn_start_layer` onwards.
        #
        # Key index constants (uppercase = fixed for this forward call):
        #   SL            : full sequence length (includes padding + vl + action tokens)
        #   ACT_START     : first action token position = SL - action_length
        #   IMG_START[b]  : first image token position per sample, read from visual_pos_masks
        #                   (argmax of the bool mask → first True position)
        #
        # Attention mask layout for non-dinov3 layers [BS, 1, SL, SL]:
        #   causal_mask_normal[b, 0, q, k] = -inf  →  q cannot attend to k
        # We add -inf to action rows (q >= ACT_START) for forbidden key columns.
        # ─────────────────────────────────────────────────────────────────────
        _action_mask_normal = None   # restricted causal_mask_normal
        _action_mask_dinov3 = None   # restricted causal_mask_with_dinov3
        _roi_attn_accum = None       # [BS, SL] running sum of action->all attention
        _roi_attn_count = 0
        _roi_pos_mask = None         # [BS, SL] selected Qwen image-token positions

        if (action_attn_mode != 'none'
                and action_img_attn_start_layer >= 0
                and action_length > 0
                and visual_pos_masks is not None
                and causal_mask_normal is not None):
            base_visual_mask = visual_pos_masks[
                : inputs_embeds.shape[0], : inputs_embeds.shape[1]
            ].to(inputs_embeds.device).bool()
            base_padding_lens = padding_lens
            if base_padding_lens is None:
                base_padding_lens = torch.zeros(
                    inputs_embeds.shape[0], dtype=torch.long, device=inputs_embeds.device
                )

            if action_attn_mode in {'pre_image', 'non_image'}:
                _action_mask_normal = _build_action_restriction_mask(
                    causal_mask_normal,
                    visual_pos_mask=base_visual_mask,
                    action_length=action_length,
                    mode=action_attn_mode,
                    dtype=inputs_embeds.dtype,
                    device=inputs_embeds.device,
                    padding_lens=base_padding_lens,
                )
                if causal_mask_with_dinov3 is not None:
                    _action_mask_dinov3 = _build_action_restriction_mask(
                        causal_mask_with_dinov3,
                        visual_pos_mask=base_visual_mask,
                        action_length=action_length,
                        mode=action_attn_mode,
                        dtype=inputs_embeds.dtype,
                        device=inputs_embeds.device,
                        expert_len=dinov3_len,
                        padding_lens=base_padding_lens,
                    )
            else:
                _roi_attn_accum = torch.zeros(
                    inputs_embeds.shape[0], inputs_embeds.shape[1],
                    device=inputs_embeds.device, dtype=torch.float32,
                )
                _roi_attn_count = 0

        # create position embeddings to be shared across the decoder layers
        # 如果有 dinov3，需要为完整序列创建 position_embeddings（包含 dinov3 + image）
        # 📌 重要：顺序必须是 [padding][dinov3][vl]，与 Attention Mask 一致
        if dinov3_len > 0:
            # 为完整序列创建 position_ids
            # 📌 重要：遵循 HuggingFace 标准做法，并按 [padding][dinov3][vl] 顺序
            batch_size = position_ids.shape[1]
            seq_len = position_ids.shape[2]
            full_seq_len = dinov3_len + seq_len
            device = position_ids.device
            
            # ============================================================
            # 📌 向量化构建 position_ids
            # ============================================================
            # 目标顺序: [padding][dinov3][vl]
            # position_ids: [3, batch, seq_len] 顺序是 [padding][vl]
            
            # 创建位置索引 [full_seq_len]
            positions = torch.arange(full_seq_len, device=device)
            
            if padding_lens is not None:
                pad_lens = padding_lens[None, :, None]  # [1, batch, 1]
            else:
                pad_lens = torch.zeros(1, batch_size, 1, dtype=torch.long, device=device)
            
            # 扩展 positions 到 [1, batch, full_seq_len]
            positions_expanded = positions[None, None, :].expand(1, batch_size, full_seq_len)
            
            # 计算三个区域的掩码: [1, batch, full_seq_len]
            is_padding = positions_expanded < pad_lens
            is_dinov3 = (positions_expanded >= pad_lens) & (positions_expanded < pad_lens + dinov3_len)
            is_vl = positions_expanded >= pad_lens + dinov3_len
            
            # 初始化 expanded_position_ids: [3, batch, full_seq_len]
            expanded_position_ids = torch.zeros(3, batch_size, full_seq_len, dtype=position_ids.dtype, device=device)
            
            # ============================================================
            # 向量化构建 expanded_position_ids
            # ============================================================
            # 目标：[padding][dinov3][vl]，其中：
            # - padding: 复制原始值
            # - dinov3: T维度 [0, 1, ..., dinov3_len-1]，H/W维度为 0
            # - vl: 复制原始值，T维度加 dinov3_len 偏移
            
            # 扩展到 3 个维度的掩码
            is_padding_3d = is_padding.expand(3, -1, -1)  # [3, batch, full_seq_len]
            is_dinov3_3d = is_dinov3.expand(3, -1, -1)
            is_vl_3d = is_vl.expand(3, -1, -1)
            
            # Step 1: 处理 padding 和 VL 部分（从原始 position_ids 提取）
            # 构建源索引：
            # - padding 位置 j: 从 position_ids[:, :, j] 读取
            # - vl 位置 j: 从 position_ids[:, :, j - dinov3_len] 读取
            source_indices = torch.where(
                is_padding | is_dinov3,  # padding 和 dinov3 区域：使用 position（临时，dinov3 会被覆盖）
                positions_expanded,
                positions_expanded - dinov3_len  # vl 区域：减去 dinov3_len
            )
            source_indices = source_indices.clamp(min=0, max=seq_len - 1)
            source_indices_3d = source_indices.expand(3, -1, -1)
            
            # 从原始 position_ids gather
            gathered_position_ids = torch.gather(position_ids, 2, source_indices_3d)
            
            # Step 2: 设置 padding 部分
            expanded_position_ids = torch.where(is_padding_3d, gathered_position_ids, expanded_position_ids)
            
            # Step 3: 设置 VL 部分
            # 📌 重要：VL 的 T 位置应该基于有效 token 的索引，不受 padding 影响
            # 即：第一个有效 VL token 使用 T=dinov3_len，第二个使用 T=dinov3_len+1，...
            vl_position_ids = gathered_position_ids.clone()
            
            # 计算 VL 在有效序列中的索引（排除 padding）
            # 对于完整序列位置 j（在 VL 区域）：
            #   - 它在有效序列中的索引 = (j - pad_len) - dinov3_len
            #   - 它的 T 位置应该是 dinov3_len + 有效索引 = j - pad_len
            vl_effective_offset = (positions_expanded - pad_lens).clamp(min=0)  # 在有效序列中的位置
            vl_t_position = torch.where(is_vl, vl_effective_offset, torch.zeros_like(vl_effective_offset))
            if vl_position_contract != "preserve_qwen_mrope":
                vl_position_ids[0] = vl_t_position
            
            # H 和 W 维度保持从原始 position_ids gather 的值
            expanded_position_ids = torch.where(is_vl_3d, vl_position_ids, expanded_position_ids)
            
            # Step 4: 设置 DINOv3 部分（T: [0,1,...,dinov3_len-1], H/W: 0）
            # 计算 DINOv3 在其自身序列中的偏移
            dinov3_indices = (positions_expanded - pad_lens).clamp(min=0, max=dinov3_len - 1)  # [1, batch, full_seq_len]
            
            # DINOv3 的 T 维度：直接使用偏移值
            dinov3_t_values = torch.where(is_dinov3, dinov3_indices, torch.zeros_like(dinov3_indices))
            expanded_position_ids[0] = torch.where(is_dinov3[0], dinov3_t_values[0], expanded_position_ids[0])
            
            # DINOv3 的 H 和 W 维度：保持为 0（已经初始化为 0，不需要额外设置）
            
            # 创建 dummy hidden_states 用于生成完整的 position_embeddings
            dummy_hidden = hidden_states.new_zeros(batch_size, full_seq_len, hidden_states.shape[-1])
            
            # 为完整序列创建 position_embeddings
            position_embeddings = self.rotary_emb(dummy_hidden, expanded_position_ids)
        else:
            # 没有 dinov3，正常创建
            position_embeddings = self.rotary_emb(hidden_states, position_ids)

        # ── Visual Token Concat: precompute mask & position_embeddings ────────
        # Reuses the same [pad][visual][vl] infrastructure as MOT/dinov3.
        # All layers receive `position_embeddings_full_visual` (size: visual_token_len + seq_len).
        # At visual layers:     dinov3_len=0  → attention sees full hidden_states normally.
        # At non-visual layers: dinov3_len=visual_token_len → attention applies VL offset.
        visual_token_len = 0
        causal_mask_with_visual = None
        padding_lens_visual = None
        position_embeddings_full_visual = None

        if visual_token_states is not None and len(visual_token_states) > 0:
            if action_attn_mode != "none":
                raise ValueError(
                    "action_attn_mode is not implemented for visual_token_states concat layers; "
                    "use MOT expert injection or disable the action restriction."
                )
            # Infer visual_token_len from first entry: Tensor[B, N, D] → N
            visual_token_len = next(iter(visual_token_states.values())).shape[1]

            # Reuse the same expanded-mask & expanded-position_ids logic as dinov3 ─────
            _stc_seq_len = inputs_embeds.shape[1]
            _stc_batch   = inputs_embeds.shape[0]
            _stc_device  = inputs_embeds.device
            _stc_full    = visual_token_len + _stc_seq_len

            # 1. padding_lens_visual ──────────────────────────────────────────
            if attention_mask is not None and attention_mask.ndim == 2:
                _has_valid = attention_mask.any(dim=1)
                padding_lens_visual = attention_mask.argmax(dim=1)
                padding_lens_visual = torch.where(
                    _has_valid, padding_lens_visual,
                    torch.full_like(padding_lens_visual, _stc_seq_len)
                )

            # 2. expanded_attention_mask for causal_mask_with_visual ──────────
            _stc_expanded_mask = None
            if attention_mask is not None and attention_mask.ndim == 2:
                _visual_ones = torch.ones(_stc_batch, visual_token_len,
                                          dtype=attention_mask.dtype, device=_stc_device)
                _stc_expanded_mask = torch.cat([attention_mask, _visual_ones], dim=1)

            _stc_dummy_input = inputs_embeds.new_zeros(_stc_batch, _stc_full, inputs_embeds.shape[-1])
            if cache_position is not None:
                _stc_full_cache_pos = torch.arange(
                    cache_position[0], cache_position[0] + _stc_full, device=cache_position.device)
            else:
                _stc_full_cache_pos = torch.arange(_stc_full, device=_stc_device)
            _stc_full_pos_ids = torch.arange(_stc_full, device=text_position_ids.device)
            _stc_full_pos_ids = _stc_full_pos_ids.unsqueeze(0).expand(text_position_ids.shape[0], -1)

            causal_mask_with_visual = create_causal_mask(
                config=self.config,
                input_embeds=_stc_dummy_input,
                attention_mask=_stc_expanded_mask,
                cache_position=_stc_full_cache_pos,
                past_key_values=None,
                position_ids=_stc_full_pos_ids,
            )

            # 3. expanded position_ids → position_embeddings_full_visual ─────
            # Same structure as dinov3: [pad][visual][vl], T-dim offset for VL.
            _positions = torch.arange(_stc_full, device=_stc_device)
            if padding_lens_visual is not None:
                _pad_lens = padding_lens_visual[None, :, None]   # [1, B, 1]
            else:
                _pad_lens = torch.zeros(1, _stc_batch, 1, dtype=torch.long, device=_stc_device)

            _positions_exp = _positions[None, None, :].expand(1, _stc_batch, _stc_full)
            _is_pad    = _positions_exp < _pad_lens
            _is_visual = (_positions_exp >= _pad_lens) & (_positions_exp < _pad_lens + visual_token_len)
            _is_vl     = _positions_exp >= _pad_lens + visual_token_len

            _is_pad_3d    = _is_pad.expand(3, -1, -1)
            _is_visual_3d = _is_visual.expand(3, -1, -1)
            _is_vl_3d     = _is_vl.expand(3, -1, -1)

            _src_idx = torch.where(
                _is_pad | _is_visual, _positions_exp,
                (_positions_exp - visual_token_len).clamp(0, _stc_seq_len - 1)
            ).clamp(0, _stc_seq_len - 1)
            _src_idx_3d = _src_idx.expand(3, -1, -1)
            _gathered_pos = torch.gather(position_ids, 2, _src_idx_3d)

            _exp_pos_ids = torch.zeros(3, _stc_batch, _stc_full,
                                       dtype=position_ids.dtype, device=_stc_device)
            _exp_pos_ids = torch.where(_is_pad_3d, _gathered_pos, _exp_pos_ids)

            # VL: T = j - pad_len (offset in valid sequence, same logic as dinov3)
            _vl_pos = _gathered_pos.clone()
            _vl_t   = ((_positions_exp - _pad_lens).clamp(min=0))
            _vl_pos[0] = torch.where(_is_vl[0], _vl_t[0], torch.zeros_like(_vl_t[0]))
            _exp_pos_ids = torch.where(_is_vl_3d, _vl_pos, _exp_pos_ids)

            # Visual tokens: T = offset within visual block, H/W = 0
            _visual_t = (_positions_exp - _pad_lens).clamp(0, visual_token_len - 1)
            _exp_pos_ids[0] = torch.where(_is_visual[0], _visual_t[0], _exp_pos_ids[0])

            _dummy_h = hidden_states.new_zeros(_stc_batch, _stc_full, hidden_states.shape[-1])
            position_embeddings_full_visual = self.rotary_emb(_dummy_h, _exp_pos_ids)

        # decoder layers
        all_hidden_states = () if output_hidden_states else None
        for layer_idx, decoder_layer in enumerate(self.layers):
            if output_hidden_states:
                all_hidden_states += (hidden_states,)
            # 准备当前层的 kwargs，传递 dinov3 相关信息
            current_layer_kwargs = kwargs.copy()

            if (
                dinov3_efficient
                and need_qwen_pruning
                and not dinov3_called_in_efficient_mode
                and dinov3_qwen_mapping
                and layer_idx >= min(int(layer) for layer in dinov3_qwen_mapping)
            ):
                raise RuntimeError(
                    "Efficient DINOv3 reached the first expert-injection layer before producing QKV. "
                    "Check pruning guidance layers and attention collection."
                )

            use_dinov3_mask = False
            if dinov3_qkv_states is not None and layer_idx in dinov3_qkv_states:
                current_layer_kwargs['dinov3_qkv'] = dinov3_qkv_states[layer_idx]
                use_dinov3_mask = True

            layer_expert_len = dinov3_len
            current_position_embeddings = position_embeddings
            if vl_position_contract in {
                "native_unmapped_layers",
                "preserve_qwen_mrope",
            } and not use_dinov3_mask:
                layer_expert_len = 0
                current_position_embeddings = self.rotary_emb(hidden_states, position_ids)

            current_layer_kwargs['dinov3_len'] = layer_expert_len
            current_layer_kwargs['padding_lens'] = padding_lens
            
            # 根据是否有 dinov3 qkv 选择对应的 causal_mask，并在指定层后应用 action 限制
            _use_restriction = (
                _action_mask_normal is not None
                and action_img_attn_start_layer >= 0
                and layer_idx >= action_img_attn_start_layer
            )
            if _use_restriction:
                if use_dinov3_mask:
                    if _action_mask_dinov3 is None:
                        raise RuntimeError(
                            "Action attention restriction is active on an expert-injection layer, "
                            "but the expanded restriction mask has not been built."
                        )
                    current_attention_mask = _action_mask_dinov3
                else:
                    current_attention_mask = _action_mask_normal
            else:
                current_attention_mask = (
                    causal_mask_with_dinov3
                    if use_dinov3_mask and causal_mask_with_dinov3 is not None
                    else causal_mask_normal
                )

            # ── Visual Token Concat: override mask / pos_emb per layer ────────
            # Token concat and MOT are mutually exclusive; token concat takes priority.
            if visual_token_states is not None and visual_token_len > 0:
                if layer_idx in visual_token_states:
                    # Expanded layer: pass aligned visual tokens to DecoderLayer.
                    # dinov3_len=0 so attention applies plain RoPE to full hidden_states.
                    current_layer_kwargs['visual_tokens']   = visual_token_states[layer_idx]
                    current_layer_kwargs['visual_token_len'] = visual_token_len
                    current_layer_kwargs['dinov3_len']       = 0
                    current_layer_kwargs['padding_lens']     = padding_lens_visual
                    current_attention_mask      = causal_mask_with_visual
                    current_position_embeddings = position_embeddings_full_visual
                else:
                    # Non-expanded layer: use VL position offset (same as non-dinov3 layers
                    # when dinov3_len > 0 — attention slices cos/sin from the full pos_emb).
                    current_layer_kwargs['dinov3_len']   = visual_token_len
                    current_layer_kwargs['padding_lens'] = padding_lens_visual
                    current_attention_mask      = causal_mask_normal
                    current_position_embeddings = position_embeddings_full_visual
            
            # ========== 判断当前层是否需要输出 attention（用于 qwen 剪枝 / roi_image 收集） ==========
            # 注意这边的 layer_idx 是从 0 开始算的
            _needs_roi_collect = (
                action_attn_mode == 'roi_image'
                and _roi_attn_accum is not None
                and _action_mask_normal is None  # not yet built
                and action_attn_roi_layer_start <= layer_idx <= action_attn_roi_layer_end
            )
            layer_needs_attention = (
                collect_attention_maps or
                _needs_roi_collect or
                # 单层剪枝：仅在 ref_layer 收集
                (
                    need_qwen_pruning and
                    not use_aggregation and
                    actual_pruning_ref_layer is not None and
                    layer_idx == actual_pruning_ref_layer and
                    not pruning_applied
                ) or
                # 多层聚合剪枝：在 [agg_layer_start, agg_layer_end] 范围内每层都收集
                (
                    use_aggregation and
                    not pruning_applied and
                    agg_layer_start <= layer_idx <= agg_layer_end
                )
            )
            
            # Attention collection is a per-layer override. Keeping it in kwargs makes
            # the implementation stable when gradient checkpointing recomputes this layer.
            if layer_needs_attention:
                current_attention_implementation = self.config._attn_implementation or "eager"
                if current_attention_implementation != "eager":
                    if attention_collection_mask_contract == "corrected_causal":
                        collection_seq_len = hidden_states.shape[1]
                        if current_layer_kwargs.get('visual_tokens') is not None:
                            collection_seq_len += int(current_layer_kwargs.get('visual_token_len', 0))
                        elif use_dinov3_mask:
                            collection_seq_len += int(current_layer_kwargs.get('dinov3_len', 0))
                        current_attention_mask = _prepare_eager_attention_collection_mask(
                            current_attention_mask,
                            batch_size=hidden_states.shape[0],
                            query_length=collection_seq_len,
                            key_length=collection_seq_len,
                            dtype=hidden_states.dtype,
                            device=hidden_states.device,
                        )
                    current_layer_kwargs["attention_implementation_override"] = "eager"
            
            # 前向传播
            layer_outputs = decoder_layer(
                hidden_states,  # [4, 279, 2560]
                attention_mask=current_attention_mask,  # [4, 1, 279, 279]
                position_ids=text_position_ids,  # [4, 279], position_ids[0], text
                past_key_values=past_key_values,
                cache_position=cache_position,  # [0 -- 278]
                position_embeddings=current_position_embeddings,  # ([4, 860, 128], [])
                output_attentions=layer_needs_attention,
                **current_layer_kwargs,
            )
            hidden_states = layer_outputs[0]
            
            # ========== qwen_action / qwen_task 剪枝逻辑 ==========
            if (
                (need_qwen_pruning or collect_attention_maps)
                and layer_needs_attention
                and len(layer_outputs) > 1
                and layer_outputs[1] is not None
            ):
                # 提取当前层的 attention weights
                attn_weights = layer_outputs[1]  # [batch, num_heads, seq_len, seq_len]
                
                # 平均所有 attention heads
                avg_attn = attn_weights.mean(dim=1)  # [batch, seq_len, seq_len]
                
                # 获取 batch_size 和 seq_len
                batch_size = avg_attn.shape[0]
                seq_len = avg_attn.shape[1]  # 当前层的序列长度（不包含 dinov3）
                
                # 获取每个样本的 padding 长度（如果没有则为 0）
                # 注意：在分布式 / 梯度累积等场景下，padding_lens 可能对应的是全局 batch，
                # 而当前 layer 的 attention 仅对应一个局部 micro-batch，因此需要对齐 batch 维度。
                if padding_lens is None:
                    sample_padding_lens = torch.zeros(batch_size, dtype=torch.long, device=avg_attn.device)
                else:
                    sample_padding_lens = padding_lens.to(avg_attn.device)
                    if sample_padding_lens.shape[0] != batch_size:
                        sample_padding_lens = sample_padding_lens[:batch_size]
                
                # Qwen3VL 的序列结构分析：
                # 训练时：[padding][prefix_tokens, image_tokens, instruction_tokens, end_tokens, action_tokens]
                # - prefix_tokens: 从 kwargs 中获取（每个样本可能不同）
                # - image_tokens: 从 visual config 获取
                # - instruction_tokens: 从 kwargs 中获取范围
                # - end_tokens: 结尾的固定 tokens
                # - action_tokens: action_length
                
                # prefix_tokens_lens 和 instruction_ranges 已经是函数的显式参数
                # 不需要从 kwargs 获取，直接使用即可
                
                # 从 visual_pos_masks 计算实际的 visual tokens 数量
                # visual_pos_masks: [batch, seq_len]，标记哪些位置是 visual tokens
                # visual_pos_masks 是函数的显式参数，直接使用
                if visual_pos_masks is None:
                    raise ValueError(
                        "Qwen-guided pruning requires visual_pos_masks; refusing the historical "
                        "hard-coded 576-token fallback."
                    )
                base_visual_mask = visual_pos_masks[:batch_size, : inputs_embeds.shape[1]].to(
                    avg_attn.device, dtype=torch.bool
                )
                visual_token_counts = base_visual_mask.sum(dim=1)
                if not torch.all(visual_token_counts > 0):
                    raise ValueError("Every sample must contain at least one Qwen visual token for pruning.")
                if not torch.all(visual_token_counts == visual_token_counts[0]):
                    raise ValueError(
                        "Batch samples have different visual token counts; current pruning code "
                        "requires fixed square Qwen visual grids per batch."
                    )
                num_visual_tokens = int(visual_token_counts[0].item())

                if prefix_tokens_lens is None:
                    raise ValueError(
                        "Qwen-guided pruning requires prefix_tokens_lens aligned to the first visual token; "
                        "refusing the historical hard-coded prefix fallback."
                    )
                prefix_tokens_lens = prefix_tokens_lens.to(
                    avg_attn.device, dtype=torch.long
                )
                if prefix_tokens_lens.shape != (batch_size,):
                    raise ValueError(
                        f"prefix_tokens_lens must have shape {(batch_size,)}; "
                        f"got {tuple(prefix_tokens_lens.shape)}."
                    )
                expected_visual_positions = (
                    prefix_tokens_lens[:, None]
                    + torch.arange(num_visual_tokens, device=avg_attn.device)[None, :]
                )
                if torch.any(expected_visual_positions >= base_visual_mask.shape[1]):
                    raise ValueError("prefix_tokens_lens places visual tokens outside the base sequence.")
                actual_visual_positions = torch.nonzero(base_visual_mask, as_tuple=False)[:, 1].view(
                    batch_size, num_visual_tokens
                )
                if not torch.equal(expected_visual_positions, actual_visual_positions):
                    raise ValueError(
                        "Qwen-guided pruning currently requires one contiguous visual-token block per sample, "
                        "and prefix_tokens_lens must point to its first token."
                    )
                
                # visual tokens 的范围，shape: [batch]
                # prefix_tokens_lens 已经包含 padding，直接使用
                visual_start_per_sample = prefix_tokens_lens  # [batch]
                visual_end_per_sample = visual_start_per_sample + num_visual_tokens  # [batch]
                
                # instruction tokens 的范围
                # 优先使用提供的 instruction_ranges
                if instruction_ranges is not None:
                    # instruction_ranges: tensor [batch, 2] 或 list[batch, 2]
                    if isinstance(instruction_ranges, torch.Tensor):
                        instruction_ranges = instruction_ranges.to(
                            avg_attn.device, dtype=torch.long
                        )
                        if instruction_ranges.shape != (batch_size, 2):
                            raise ValueError(
                                f"instruction_ranges must have shape {(batch_size, 2)}; "
                                f"got {tuple(instruction_ranges.shape)}."
                            )
                        instruction_start_per_sample = instruction_ranges[:, 0]  # [batch]
                        instruction_end_per_sample = instruction_ranges[:, 1]    # [batch]
                    else:
                        if len(instruction_ranges) != batch_size:
                            raise ValueError(
                                "instruction_ranges list length must match the attention batch; "
                                f"got {len(instruction_ranges)} for batch {batch_size}."
                            )
                        instruction_start_per_sample = torch.tensor(
                            [r[0] for r in instruction_ranges],
                            dtype=torch.long,
                            device=avg_attn.device,
                        )
                        instruction_end_per_sample = torch.tensor(
                            [r[1] for r in instruction_ranges],
                            dtype=torch.long,
                            device=avg_attn.device,
                        )
                    if torch.any(instruction_start_per_sample < visual_end_per_sample):
                        raise ValueError("instruction_ranges overlaps the Qwen visual-token block.")
                    if torch.any(instruction_end_per_sample < instruction_start_per_sample):
                        raise ValueError("instruction_ranges end must not precede its start.")
                else:
                    # 默认：instruction 在 visual_end + 1 开始
                    instruction_start_per_sample = visual_end_per_sample + 1  # [batch]，+1 跳过 <end image>

                    # The fallback metadata is expressed in base [padding][VL]
                    # coordinates even when this layer's attention matrix is expanded.
                    base_attention_seq_len = seq_len - (dinov3_len if use_dinov3_mask else 0)
                    base_action_start_per_sample = torch.full(
                        (batch_size,),
                        base_attention_seq_len - action_length,
                        dtype=torch.long,
                        device=avg_attn.device,
                    )  # [batch]

                    # instruction 在 visual_end + 1 到 action_start 之间
                    instruction_end_per_sample = base_action_start_per_sample  # [batch]
                
                # action 区间由 _resolve_pruning_guidance_indices 内部按
                # attention_seq_len - action_length 解析（guidance_indices.action_start）。

                guidance_indices = _resolve_pruning_guidance_indices(
                    visual_start_per_sample=visual_start_per_sample,
                    instruction_start_per_sample=instruction_start_per_sample,
                    instruction_end_per_sample=instruction_end_per_sample,
                    attention_seq_len=seq_len,
                    action_length=action_length,
                    padding_lens=sample_padding_lens,
                    expert_len=dinov3_len,
                    expanded_sequence=(
                        use_dinov3_mask
                        and pruning_attention_index_contract == "expanded_sequence"
                    ),
                )
                guidance_visual_start_per_sample = guidance_indices.visual_start
                guidance_instruction_start_per_sample = guidance_indices.instruction_start
                guidance_instruction_end_per_sample = guidance_indices.instruction_end
                guidance_action_start_per_sample = guidance_indices.action_start
                
                attention_to_visual = None
                attention_map_resized = None

                # 使用向量化索引提取 attention
                attention_to_visual = None
                if pruning_mode == 'qwen_action' or (collect_attention_maps and pruning_mode not in ['qwen_action', 'qwen_task']):
                    # 提取 action tokens 对 visual tokens 的 attention
                    # avg_attn: [batch, seq_len, seq_len]
                    
                    # ========== 使用 torch.gather 实现（更高效）==========
                    # Step 1: 创建 action tokens 的索引 [batch, action_length]
                    action_offsets = torch.arange(action_length, device=avg_attn.device)[None, :]
                    action_indices = guidance_action_start_per_sample[:, None] + action_offsets
                    action_indices = torch.clamp(action_indices, min=0, max=seq_len - 1)
                    
                    # Step 2: 扩展索引以提取 action tokens 的注意力行
                    action_indices_expanded = action_indices[:, :, None].expand(-1, -1, seq_len)  # [batch, action_len, seq_len]
                    
                    # 使用 gather 提取 action tokens 的注意力
                    # [batch, action_length, seq_len]
                    action_attn = torch.gather(avg_attn, dim=1, index=action_indices_expanded)
                    
                    # Step 3: 创建 visual tokens 的索引并提取对应的注意力
                    visual_offsets = torch.arange(num_visual_tokens, device=avg_attn.device)[None, None, :]  # [1, 1, num_visual]
                    visual_indices = visual_offsets + guidance_visual_start_per_sample[:, None, None]
                    visual_indices = visual_indices.expand(-1, action_length, -1)  # [batch, action_len, num_visual]
                    
                    # 使用 gather 提取对 visual tokens 的注意力
                    # [batch, action_length, num_visual_tokens]
                    action_to_visual = torch.gather(action_attn, dim=2, index=visual_indices)
                    
                    # 平均所有 action tokens 的 attention: [batch, num_visual_tokens]
                    attention_to_visual = action_to_visual.mean(dim=1)

                    # action_task_mean: 同层同时计算 task→visual attention 并取均值
                    if pruning_attn_aggregation == 'action_task_mean':
                        instruction_len_per_sample_at = (
                            guidance_instruction_end_per_sample
                            - guidance_instruction_start_per_sample
                        )
                        max_instruction_len_at = instruction_len_per_sample_at.max().item()
                        if max_instruction_len_at <= 0:
                            max_instruction_len_at = 1
                            _instr_start_at = (
                                guidance_visual_start_per_sample + num_visual_tokens + 1
                            )
                            _instr_end_at = _instr_start_at + 1
                        else:
                            _instr_start_at = guidance_instruction_start_per_sample
                            _instr_end_at = guidance_instruction_end_per_sample
                        instr_offsets_at = torch.arange(max_instruction_len_at, device=avg_attn.device)[None, :]
                        instr_indices_at = _instr_start_at[:, None] + instr_offsets_at
                        instr_mask_at = instr_indices_at < _instr_end_at[:, None]
                        instr_indices_at = torch.clamp(instr_indices_at, min=0, max=seq_len - 1)
                        instr_indices_at_exp = instr_indices_at[:, :, None].expand(-1, -1, seq_len)
                        instr_attn_at = torch.gather(avg_attn, dim=1, index=instr_indices_at_exp)
                        visual_indices_at = (
                            torch.arange(num_visual_tokens, device=avg_attn.device)[None, None, :]
                            + guidance_visual_start_per_sample[:, None, None]
                        ).expand(-1, max_instruction_len_at, -1)
                        task_to_visual_at = torch.gather(instr_attn_at, dim=2, index=visual_indices_at)
                        task_to_visual_at = task_to_visual_at * instr_mask_at[:, :, None].float()
                        valid_at = instruction_len_per_sample_at.float()[:, None].clamp(min=1.0)
                        task_attn_at = task_to_visual_at.sum(dim=1) / valid_at
                        attention_to_visual = _combine_action_task_attention(
                            attention_to_visual,
                            task_attn_at,
                            contract=action_task_attention_contract,
                        )

                elif pruning_mode == 'qwen_task':
                    # 提取 task instruction tokens 对 visual tokens 的 attention
                    
                    # 计算 instruction 长度
                    # instruction_start_per_sample 和 instruction_end_per_sample 现在都是 [batch] shape
                    instruction_len_per_sample = (
                        guidance_instruction_end_per_sample
                        - guidance_instruction_start_per_sample
                    )
                    max_instruction_len = instruction_len_per_sample.max().item()
                    
                    # 确保至少有 1 个 instruction token
                    if max_instruction_len <= 0:
                        # 如果没有 instruction tokens，回退到使用所有非 action tokens
                        max_instruction_len = 1
                        guidance_instruction_start_per_sample = (
                            guidance_visual_start_per_sample + num_visual_tokens + 1
                        )
                        guidance_instruction_end_per_sample = (
                            guidance_instruction_start_per_sample + 1
                        )
                        instruction_len_per_sample = torch.ones(batch_size, dtype=torch.long, device=avg_attn.device)
                    
                    # ========== 使用 torch.gather 实现（更高效）==========
                    # Step 1: 创建 instruction tokens 的索引
                    # [batch, max_instruction_len]
                    instruction_offsets = torch.arange(max_instruction_len, device=avg_attn.device)[None, :]
                    instruction_indices = (
                        guidance_instruction_start_per_sample[:, None] + instruction_offsets
                    )
                    
                    # 创建 mask：只有当索引 < instruction_end_per_sample 时才有效
                    instruction_mask = (
                        instruction_indices < guidance_instruction_end_per_sample[:, None]
                    )
                    
                    # 确保索引不越界
                    instruction_indices = torch.clamp(instruction_indices, min=0, max=seq_len - 1)
                    
                    # Step 2: 为每个 instruction token 提取其对所有 tokens 的注意力
                    # avg_attn: [batch, seq_len, seq_len]
                    # 扩展 instruction_indices 以匹配 gather 的维度
                    instruction_indices_expanded = instruction_indices[:, :, None].expand(-1, -1, seq_len)  # [batch, max_instr, seq_len]
                    
                    # 使用 gather 提取 instruction tokens 的注意力行
                    # [batch, max_instruction_len, seq_len]
                    instruction_attn = torch.gather(avg_attn, dim=1, index=instruction_indices_expanded)
                    
                    # Step 3: 从每一行中提取对 visual tokens 的注意力
                    # 创建 visual tokens 的索引
                    visual_offsets = torch.arange(num_visual_tokens, device=avg_attn.device)[None, None, :]  # [1, 1, num_visual]
                    visual_indices = visual_offsets + guidance_visual_start_per_sample[:, None, None]
                    visual_indices = visual_indices.expand(-1, max_instruction_len, -1)  # [batch, max_instr, num_visual]
                    
                    # 使用 gather 提取对 visual tokens 的注意力
                    # [batch, max_instruction_len, num_visual_tokens]
                    task_to_visual = torch.gather(instruction_attn, dim=2, index=visual_indices)
                    
                    # 应用 mask
                    instruction_mask_expanded = instruction_mask[:, :, None]  # [batch, max_instr, 1]
                    task_to_visual = task_to_visual * instruction_mask_expanded.float()
                    
                    # 平均所有有效的 instruction tokens: [batch, num_visual_tokens]
                    valid_token_counts = instruction_len_per_sample.float()[:, None].clamp(min=1.0)  # [batch, 1]，避免除以0
                    attention_to_visual = task_to_visual.sum(dim=1) / valid_token_counts

                if collect_attention_maps:
                    attention_to_visual_all_layers.append(attention_to_visual)

                # 聚合模式：在聚合层范围内缓存每层的 attention_to_visual（Qwen 分辨率）
                if use_aggregation and attention_to_visual is not None and agg_layer_start <= layer_idx <= agg_layer_end:
                    _agg_attn_cache.append(attention_to_visual.detach().float())

                # 对 attention map 进行插值，从 Qwen visual token 分辨率调整到 expert 分辨率。
                # Efficient mode has no QKV yet, so its source grid comes from pixels/config.
                expert_source_available = (
                    (dinov3_qkv_states is not None and len(dinov3_qkv_states) > 0)
                    or (dinov3_efficient and dinov3_model is not None and dinov3_pixel_values is not None)
                )
                if expert_source_available:
                    qwen_visual_h, qwen_visual_w = _require_square_token_grid(
                        num_visual_tokens,
                        "Qwen visual",
                    )
                    if dinov3_qkv_states is not None and len(dinov3_qkv_states) > 0:
                        dinov3_num_tokens, dinov3_visual_h, dinov3_visual_w = _expert_patch_grid(
                            unpruned_dinov3_len,
                            expert_num_prefix_tokens,
                            "DINOv3/SigLIP expert",
                            expert_patch_grid_contract,
                        )
                    else:
                        patch_size = getattr(getattr(dinov3_model, "config", None), "patch_size", 16)
                        dinov3_visual_h, dinov3_visual_w = _expert_patch_grid_from_pixels(
                            dinov3_pixel_values,
                            patch_size,
                        )
                        dinov3_num_tokens = dinov3_visual_h * dinov3_visual_w
                        expected_unpruned_len = dinov3_num_tokens + expert_num_prefix_tokens
                        if expected_unpruned_len != unpruned_dinov3_len:
                            raise RuntimeError(
                                "Efficient expert source-length contract drift: "
                                f"pixels/config imply {expected_unpruned_len} tokens, "
                                f"but the outer model passed {unpruned_dinov3_len}."
                            )

                    # 安全检查：分辨率为0时跳过插值（避免 CUDA device-side assert）
                    if qwen_visual_h <= 0 or dinov3_visual_h <= 0:
                        latest_attention_map_resized = None
                        if collect_attention_maps:
                            attention_map_resized_all_layers.append(None)
                    else:
                        # Reshape attention map: [batch, N] -> [batch, h, w]
                        attention_map_2d = attention_to_visual.view(
                            batch_size, qwen_visual_h, qwen_visual_w)

                        # 双线性插值到 DINOv3/SigLIP 分辨率
                        attention_map_2d = attention_map_2d.unsqueeze(1)  # [batch, 1, h, w]
                        attention_map_resized = torch.nn.functional.interpolate(
                            attention_map_2d.float(),
                            size=(dinov3_visual_h, dinov3_visual_w),
                            mode='bicubic',
                            align_corners=False
                        ).squeeze(1)  # [batch, dinov3_h, dinov3_w]

                        # Flatten: [batch, dinov3_h, dinov3_w] -> [batch, dinov3_num_tokens]
                        attention_map_resized = attention_map_resized.view(batch_size, -1)
                        latest_attention_map_resized = attention_map_resized
                        if collect_attention_maps:
                            attention_map_resized_all_layers.append(attention_map_resized)

                    # ================================================================
                    # 剪枝触发判断
                    # 单层：在 ref_layer 且尚未剪枝时立即执行
                    single_layer_prune = (
                        need_qwen_pruning and
                        not use_aggregation and
                        actual_pruning_ref_layer is not None and
                        layer_idx == actual_pruning_ref_layer and
                        not pruning_applied
                    )
                    # 多层聚合：在聚合结束层（agg_layer_end）收集完毕后触发一次
                    aggregation_prune = (
                        use_aggregation and
                        layer_idx == agg_layer_end and
                        not pruning_applied and
                        len(_agg_attn_cache) > 0
                    )
                    # ================================================================

                    if single_layer_prune or aggregation_prune:
                        # --------------------------------------------------------
                        # 决定最终用于剪枝的 attention_map（DINOv3 patch token 分辨率）
                        # --------------------------------------------------------
                        if aggregation_prune:
                            strict_candidate_mask_qwen = None
                            # 将缓存的多层 attention（Qwen 分辨率）聚合，再插值到 DINOv3 分辨率
                            if pruning_attn_aggregation == 'mean_layers':
                                # 各层均值
                                agg_attn_qwen = torch.stack(_agg_attn_cache, dim=0).mean(dim=0)  # [batch, num_visual]
                            elif pruning_attn_aggregation == 'vote':
                                if pruning_ratio > 1:
                                    _vote_k = int(pruning_ratio)
                                else:
                                    _vote_k = int(num_visual_tokens * (1.0 - pruning_ratio))
                                _vote_k = max(1, min(_vote_k, num_visual_tokens))
                                agg_attn_qwen = aggregate_sparse_topk_attention(
                                    _agg_attn_cache,
                                    topk=_vote_k,
                                    mode="vote",
                                    vote_ratio=pruning_attn_aggregation_vote_ratio,
                                    contract=pruning_vote_contract,
                                )
                                if pruning_vote_contract == "strict_ceil_fail_closed":
                                    strict_candidate_mask_qwen = agg_attn_qwen > 0
                            elif pruning_attn_aggregation == 'intersection':
                                if pruning_ratio > 1:
                                    _inter_k = int(pruning_ratio)
                                else:
                                    _inter_k = int(num_visual_tokens * (1.0 - pruning_ratio))
                                _inter_k = max(1, min(_inter_k, num_visual_tokens))
                                agg_attn_qwen = aggregate_sparse_topk_attention(
                                    _agg_attn_cache,
                                    topk=_inter_k,
                                    mode="intersection",
                                    vote_ratio=1.0,
                                    contract=pruning_vote_contract,
                                )
                                if pruning_vote_contract == "strict_ceil_fail_closed":
                                    strict_candidate_mask_qwen = agg_attn_qwen > 0
                            elif pruning_attn_aggregation == 'action_task_mean':
                                # 每层已在提取时做了 action+task 平均，直接跨层均值
                                agg_attn_qwen = torch.stack(_agg_attn_cache, dim=0).mean(dim=0)
                            else:
                                agg_attn_qwen = torch.stack(_agg_attn_cache, dim=0).mean(dim=0)

                            # 记录聚合后的 Qwen-resolution attention，供外部可视化使用
                            latest_aggregated_attention_to_visual = agg_attn_qwen.detach()

                            # 插值到 DINOv3 分辨率
                            agg_map_2d = agg_attn_qwen.view(batch_size, qwen_visual_h, qwen_visual_w).unsqueeze(1)
                            pruning_attention_map = torch.nn.functional.interpolate(
                                agg_map_2d,
                                size=(dinov3_visual_h, dinov3_visual_w),
                                mode='bicubic',
                                align_corners=False,
                            ).squeeze(1).view(batch_size, -1)  # [batch, dinov3_num_tokens]
                            strict_candidate_mask = None
                            if strict_candidate_mask_qwen is not None:
                                strict_candidate_mask = torch.nn.functional.interpolate(
                                    strict_candidate_mask_qwen.view(
                                        batch_size,
                                        1,
                                        qwen_visual_h,
                                        qwen_visual_w,
                                    ).float(),
                                    size=(dinov3_visual_h, dinov3_visual_w),
                                    mode="nearest",
                                ).squeeze(1).view(batch_size, -1).to(torch.bool)
                        else:
                            # 单层：直接使用当前层的 attention_to_visual（Qwen 分辨率）
                            latest_aggregated_attention_to_visual = attention_to_visual.detach()
                            pruning_attention_map = attention_map_resized
                            strict_candidate_mask = None

                        # --------------------------------------------------------
                        # 根据 pruning_attention_map 选 top-K patch tokens 并裁剪 QKV
                        # --------------------------------------------------------
                        num_tokens_to_keep = _pruned_patch_token_count(
                            dinov3_num_tokens,
                            pruning_ratio,
                        )

                        # 选择 top-K tokens
                        token_keep_indices_for_dinov3 = select_pruning_patch_indices(
                            pruning_attention_map,
                            num_tokens_to_keep=num_tokens_to_keep,
                            order=expert_token_order,
                            eligibility_mask=strict_candidate_mask,
                            fail_on_insufficient_candidates=strict_candidate_mask is not None,
                        )

                        # ========== Efficient DinoV3 Mode: 在这里调用 DinoV3 ==========
                        if dinov3_efficient and not dinov3_called_in_efficient_mode and dinov3_model is not None:
                            # 调用 DinoV3，只处理 top-K 的 patch tokens
                            # DinoV3 会自动保留 CLS + register tokens
                            if train_dinov3_full_finetune:
                                dinov3_outputs = dinov3_model(
                                    pixel_values=dinov3_pixel_values,
                                    output_qkv=True,
                                    qkv_after_rope=dinov3_qkv_after_rope,
                                    token_keep_indices=token_keep_indices_for_dinov3,
                                )
                            else:
                                with torch.no_grad():
                                    dinov3_outputs = dinov3_model(
                                        pixel_values=dinov3_pixel_values,
                                        output_qkv=True,
                                        qkv_after_rope=dinov3_qkv_after_rope,
                                        token_keep_indices=token_keep_indices_for_dinov3,
                                    )
                            
                            # 获取 QKV states（已经是剪枝后的）
                            dinov3_qkv_list = dinov3_outputs.qkv_states  # List[dict{'query', 'key', 'value'}]
                            
                            # 通过 aligner 转换为 Qwen 格式（如果 aligner 存在的话）
                            if dinov3_aligner is not None:
                                # aligner.forward 接受: Dict[dinov3_layer: qkv_dict]
                                # 返回: Dict[qwen_layer: aligned_qkv_dict]
                                # 首先构建 dinov3_layer_qkv 格式
                                needed_dinov3_layers = set(dinov3_qwen_mapping.values())
                                dinov3_layer_qkv = {
                                    i: qkv for i, qkv in enumerate(dinov3_qkv_list)
                                    if i in needed_dinov3_layers
                                }
                                # 调用 aligner
                                dinov3_qkv_states = dinov3_aligner(dinov3_layer_qkv)
                            else:
                                # 没有 aligner：直接使用 mapping（假设维度匹配）
                                dinov3_qkv_states = {}
                                for qwen_layer, dinov3_layer in dinov3_qwen_mapping.items():
                                    if dinov3_layer < len(dinov3_qkv_list):
                                        dinov3_qkv_states[qwen_layer] = dinov3_qkv_list[dinov3_layer]
                            
                            # 标记已调用
                            dinov3_called_in_efficient_mode = True
                            
                            # 重要：efficient 模式下，DinoV3 的输出已经是剪枝后的，不需要再次剪枝
                            # 因此直接更新 dinov3_len（这应该与提前计算的一致）
                            expected_dinov3_len = num_tokens_to_keep + expert_num_prefix_tokens
                            if expected_dinov3_len != dinov3_len:
                                raise RuntimeError(
                                    "Efficient expert length mismatch after pruning: "
                                    f"expected={expected_dinov3_len}, mask/position length={dinov3_len}."
                                )
                            if not dinov3_qkv_states:
                                raise RuntimeError(
                                    "Efficient DINOv3 produced no QKV states for the configured Qwen mapping."
                                )
                            actual_lengths = {
                                int(qkv["query"].shape[2]) for qkv in dinov3_qkv_states.values()
                            }
                            if actual_lengths != {dinov3_len}:
                                raise RuntimeError(
                                    "Efficient DINOv3 QKV length does not match precomputed mask/position length; "
                                    f"got {sorted(actual_lengths)}, expected {dinov3_len}."
                                )
                            
                            # 标记剪枝已应用，释放聚合缓存
                            pruning_applied = True
                            _agg_attn_cache.clear()
                            
                            # 注意：在 efficient 模式下，跳过后续的手动剪枝逻辑
                            #（下方 `elif not dinov3_efficient` 分支），因为 DinoV3 已经返回了剪枝后的 QKV
                        # ========== 正常模式：对预计算的 dinov3_qkv_states 进行剪枝 ==========
                        elif not dinov3_efficient:
                            # 对所有 dinov3_qkv_states 进行剪枝
                            pruned_dinov3_qkv_states = {}
                            for qwen_layer, qkv_dict in dinov3_qkv_states.items():
                                batch_size = qkv_dict['query'].shape[0]
                                num_heads_q = qkv_dict['query'].shape[1]
                                num_heads_kv = qkv_dict['key'].shape[1]  # GQA: k/v 可能头数不同
                                head_dim = qkv_dict['query'].shape[3]

                                # 保留所有显式 prefix token，再接 top-K patch token。
                                global_indices = _expert_global_keep_indices(
                                    token_keep_indices_for_dinov3,
                                    expert_num_prefix_tokens,
                                )

                                pruned_qkv = {}
                                for qkv_type in ['query', 'key', 'value']:
                                    if qkv_type not in qkv_dict:
                                        continue
                                    qkv_tensor = qkv_dict[qkv_type]  # [batch, num_heads, total_tokens, head_dim]
                                    num_heads = num_heads_q if qkv_type == 'query' else num_heads_kv
                                    expanded_indices = global_indices.unsqueeze(1).unsqueeze(-1).expand(
                                        batch_size, num_heads, -1, head_dim
                                    )
                                    pruned_qkv[qkv_type] = torch.gather(qkv_tensor, dim=2, index=expanded_indices)

                                pruned_dinov3_qkv_states[qwen_layer] = pruned_qkv

                            # 更新 dinov3_qkv_states
                            dinov3_qkv_states = pruned_dinov3_qkv_states

                            # 验证 dinov3_len（应该与提前计算的一致）
                            expected_dinov3_len = num_tokens_to_keep + expert_num_prefix_tokens
                            if expected_dinov3_len != dinov3_len:
                                raise RuntimeError(
                                    "Pruned expert length does not match precomputed mask/position length: "
                                    f"expected={expected_dinov3_len}, actual={dinov3_len}."
                                )

                            # 标记剪枝已应用，释放聚合缓存
                            pruning_applied = True
                            _agg_attn_cache.clear()

                            # 注意：不需要重新创建 causal_mask_with_dinov3 和 expanded_attention_mask
                            # 因为我们在 decoder loop 开始前就已经使用正确的（剪枝后的）dinov3_len 创建了它们
                            # 这样可以确保 position embeddings、causal mask 等从一开始就使用正确的尺寸
                elif collect_attention_maps:
                    attention_map_resized_all_layers.append(None)
            elif collect_attention_maps:
                attention_to_visual_all_layers.append(None)
                attention_map_resized_all_layers.append(None)

            # ── roi_image mode: accumulate attention, build mask after last ROI layer ──
            if _needs_roi_collect and len(layer_outputs) > 1 and layer_outputs[1] is not None:
                _attn = layer_outputs[1]  # [BS, heads, SL, SL]
                if _attn.shape[-1] != inputs_embeds.shape[1]:
                    raise RuntimeError(
                        "roi_image guidance must be collected before expert/token-concat injection; "
                        f"got attention length {_attn.shape[-1]} for base length {inputs_embeds.shape[1]}."
                    )
                # Average over heads, then average action rows → score per key [BS, SL]
                _act_to_all = _attn[:, :, -action_length:, :].mean(dim=1).mean(dim=1)
                _roi_attn_accum = _roi_attn_accum + _act_to_all.float()
                _roi_attn_count += 1

                # After the final ROI collection layer, build the restricted mask
                if layer_idx == action_attn_roi_layer_end:
                    # ROI_SCORES: zero out non-image positions, keep only image scores
                    ROI_SCORES = _roi_attn_accum / max(_roi_attn_count, 1)        # [BS, SL]
                    ROI_SCORES = ROI_SCORES.masked_fill(~base_visual_mask, float("-inf"))

                    # Per-sample top-k image tokens → ROI_IMG_MASK [BS, SL]
                    ROI_IMG_MASK = torch.zeros_like(base_visual_mask)
                    for _b in range(base_visual_mask.shape[0]):
                        _num_image = int(base_visual_mask[_b].sum().item())
                        if _num_image <= 0:
                            raise RuntimeError(f"roi_image sample {_b} has no visual tokens.")
                        _n = max(1, min(_num_image, int(_num_image * action_attn_roi_ratio)))
                        _, _topk_idx = ROI_SCORES[_b].topk(_n)
                        ROI_IMG_MASK[_b, _topk_idx] = True

                    _roi_pos_mask = ROI_IMG_MASK
                    _action_mask_normal = _build_action_restriction_mask(
                        causal_mask_normal,
                        visual_pos_mask=base_visual_mask,
                        roi_pos_mask=_roi_pos_mask,
                        action_length=action_length,
                        mode="roi_image",
                        dtype=inputs_embeds.dtype,
                        device=inputs_embeds.device,
                        padding_lens=base_padding_lens,
                    )
                    if causal_mask_with_dinov3 is not None:
                        _action_mask_dinov3 = _build_action_restriction_mask(
                            causal_mask_with_dinov3,
                            visual_pos_mask=base_visual_mask,
                            roi_pos_mask=_roi_pos_mask,
                            action_length=action_length,
                            mode="roi_image",
                            dtype=inputs_embeds.dtype,
                            device=inputs_embeds.device,
                            expert_len=dinov3_len,
                            padding_lens=base_padding_lens,
                        )

            # add visual features to the hidden states of first several layers
            if deepstack_visual_embeds is not None and layer_idx in range(len(deepstack_visual_embeds)):
                hidden_states = self._deepstack_process(
                    hidden_states,
                    visual_pos_masks,
                    deepstack_visual_embeds[layer_idx],
                )

        hidden_states = self.norm(hidden_states)
        if output_hidden_states:
            all_hidden_states += (hidden_states,)

        model_outputs = BaseModelOutputWithPast(
            last_hidden_state=hidden_states,
            past_key_values=past_key_values,
            hidden_states=all_hidden_states,
        )
        if collect_attention_maps:
            model_outputs.attention_to_visual_all_layers = attention_to_visual_all_layers
            model_outputs.attention_map_resized_all_layers = attention_map_resized_all_layers
            model_outputs.attention_map_resized = latest_attention_map_resized
        # 无论是否 collect_attention_maps，只要有聚合结果就返回（供可视化直接使用）
        if latest_aggregated_attention_to_visual is not None:
            model_outputs.aggregated_attention_to_visual = latest_aggregated_attention_to_visual
        return model_outputs

    def _deepstack_process(
        self, hidden_states: torch.Tensor, visual_pos_masks: torch.Tensor, visual_embeds: torch.Tensor
    ):
        visual_pos_masks = visual_pos_masks.to(hidden_states.device)
        visual_embeds = visual_embeds.to(hidden_states.device, hidden_states.dtype)
        local_this = hidden_states[visual_pos_masks, :].clone() + visual_embeds
        hidden_states[visual_pos_masks, :] = local_this
        return hidden_states


@auto_docstring
class Qwen3VLModel(Qwen3VLPreTrainedModel):
    base_model_prefix = ""
    _checkpoint_conversion_mapping = {}
    # Reference: fix gemma3 grad acc #37208
    accepts_loss_kwargs = False
    config: Qwen3VLConfig
    _no_split_modules = ["Qwen3VLTextDecoderLayer", "Qwen3VLVisionBlock"]

    def __init__(self, config):
        super().__init__(config)
        self.visual = Qwen3VLVisionModel._from_config(config.vision_config)
        self.language_model = Qwen3VLTextModel._from_config(config.text_config)
        self.rope_deltas = None  # cache rope_deltas here

        # Initialize weights and apply final processing
        self.post_init()

    def get_input_embeddings(self):
        return self.language_model.get_input_embeddings()

    def set_input_embeddings(self, value):
        self.language_model.set_input_embeddings(value)

    def set_decoder(self, decoder):
        self.language_model = decoder

    def get_decoder(self):
        return self.language_model

    def get_rope_index(
        self,
        input_ids: Optional[torch.LongTensor] = None,
        image_grid_thw: Optional[torch.LongTensor] = None,
        video_grid_thw: Optional[torch.LongTensor] = None,
        attention_mask: Optional[torch.Tensor] = None,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        """Different from the original implementation, Qwen3VL use timestamps rather than absolute time position ids."""

        # Since we use timestamps to seperate videos, like <t1> <vision_start> <frame1> <vision_end> <t2> <vision_start> <frame2> <vision_end>, the video_grid_thw should also be split
        if video_grid_thw is not None:
            video_grid_thw = torch.repeat_interleave(video_grid_thw, video_grid_thw[:, 0], dim=0)
            video_grid_thw[:, 0] = 1

        spatial_merge_size = self.config.vision_config.spatial_merge_size
        image_token_id = self.config.image_token_id
        video_token_id = self.config.video_token_id
        vision_start_token_id = self.config.vision_start_token_id
        mrope_position_deltas = []
        if input_ids is not None and (image_grid_thw is not None or video_grid_thw is not None):
            total_input_ids = input_ids
            if attention_mask is None:
                attention_mask = torch.ones_like(total_input_ids)
            position_ids = torch.ones(
                3,
                input_ids.shape[0],
                input_ids.shape[1],
                dtype=input_ids.dtype,
                device=input_ids.device,
            )
            image_index, video_index = 0, 0
            attention_mask = attention_mask.to(total_input_ids.device)
            for i, input_ids in enumerate(total_input_ids):
                input_ids = input_ids[attention_mask[i] == 1]
                image_nums, video_nums = 0, 0
                vision_start_indices = torch.argwhere(input_ids == vision_start_token_id).squeeze(1)
                vision_tokens = input_ids[vision_start_indices + 1]
                image_nums = (vision_tokens == image_token_id).sum()
                video_nums = (vision_tokens == video_token_id).sum()
                input_tokens = input_ids.tolist()
                llm_pos_ids_list: list = []
                st = 0
                remain_images, remain_videos = image_nums, video_nums
                for _ in range(image_nums + video_nums):
                    if image_token_id in input_tokens and remain_images > 0:
                        ed_image = input_tokens.index(image_token_id, st)
                    else:
                        ed_image = len(input_tokens) + 1
                    if video_token_id in input_tokens and remain_videos > 0:
                        ed_video = input_tokens.index(video_token_id, st)
                    else:
                        ed_video = len(input_tokens) + 1
                    if ed_image < ed_video:
                        t, h, w = (
                            image_grid_thw[image_index][0],
                            image_grid_thw[image_index][1],
                            image_grid_thw[image_index][2],
                        )
                        image_index += 1
                        remain_images -= 1
                        ed = ed_image

                    else:
                        t, h, w = (
                            video_grid_thw[video_index][0],
                            video_grid_thw[video_index][1],
                            video_grid_thw[video_index][2],
                        )
                        video_index += 1
                        remain_videos -= 1
                        ed = ed_video
                    llm_grid_t, llm_grid_h, llm_grid_w = (
                        t.item(),
                        h.item() // spatial_merge_size,
                        w.item() // spatial_merge_size,
                    )
                    text_len = ed - st

                    st_idx = llm_pos_ids_list[-1].max() + 1 if len(llm_pos_ids_list) > 0 else 0
                    llm_pos_ids_list.append(torch.arange(text_len).view(1, -1).expand(3, -1) + st_idx)

                    # t_index is always 0 because llm_grid_t is always 1 (we use timestamps to encode the temporal information for videos)
                    t_index = torch.arange(llm_grid_t).view(-1, 1).expand(-1, llm_grid_h * llm_grid_w).flatten()
                    h_index = torch.arange(llm_grid_h).view(1, -1, 1).expand(llm_grid_t, -1, llm_grid_w).flatten()
                    w_index = torch.arange(llm_grid_w).view(1, 1, -1).expand(llm_grid_t, llm_grid_h, -1).flatten()
                    llm_pos_ids_list.append(torch.stack([t_index, h_index, w_index]) + text_len + st_idx)
                    st = ed + llm_grid_t * llm_grid_h * llm_grid_w

                if st < len(input_tokens):
                    st_idx = llm_pos_ids_list[-1].max() + 1 if len(llm_pos_ids_list) > 0 else 0
                    text_len = len(input_tokens) - st
                    llm_pos_ids_list.append(torch.arange(text_len).view(1, -1).expand(3, -1) + st_idx)

                llm_positions = torch.cat(llm_pos_ids_list, dim=1).reshape(3, -1)
                position_ids[..., i, attention_mask[i] == 1] = llm_positions.to(position_ids.device)
                mrope_position_deltas.append(llm_positions.max() + 1 - len(total_input_ids[i]))
            mrope_position_deltas = torch.tensor(mrope_position_deltas, device=input_ids.device).unsqueeze(1)
            return position_ids, mrope_position_deltas
        else:
            if attention_mask is not None:
                position_ids = attention_mask.long().cumsum(-1) - 1
                position_ids.masked_fill_(attention_mask == 0, 1)
                position_ids = position_ids.unsqueeze(0).expand(3, -1, -1).to(attention_mask.device)
                max_position_ids = position_ids.max(0, keepdim=False)[0].max(-1, keepdim=True)[0]
                mrope_position_deltas = max_position_ids + 1 - attention_mask.shape[-1]
            else:
                position_ids = (
                    torch.arange(input_ids.shape[1], device=input_ids.device)
                    .view(1, 1, -1)
                    .expand(3, input_ids.shape[0], -1)
                )
                mrope_position_deltas = torch.zeros(
                    [input_ids.shape[0], 1],
                    device=input_ids.device,
                    dtype=input_ids.dtype,
                )

            return position_ids, mrope_position_deltas

    def get_video_features(
        self, pixel_values_videos: torch.FloatTensor, video_grid_thw: Optional[torch.LongTensor] = None
    ):
        """
        Encodes videos into continuous embeddings that can be forwarded to the language model. The deepstack visual features are also returned.

        Args:
            pixel_values_videos (`torch.FloatTensor` of shape `(batch_size, num_channels, image_size, image_size)`):
                The tensors corresponding to the input videos.
            video_grid_thw (`torch.LongTensor` of shape `(num_videos, 3)`, *optional*):
                The temporal, height and width of feature shape of each video in LLM.
        """
        # Same implementation as for images
        return self.get_image_features(pixel_values_videos, video_grid_thw)

    def get_image_features(self, pixel_values: torch.FloatTensor, image_grid_thw: Optional[torch.LongTensor] = None):
        """
        Encodes images into continuous embeddings that can be forwarded to the language model. The deepstack visual features are also returned.

        Args:
            pixel_values (`torch.FloatTensor` of shape `(batch_size, num_channels, image_size, image_size)`):
                The tensors corresponding to the input images.
            image_grid_thw (`torch.LongTensor` of shape `(num_images, 3)`, *optional*):
                The temporal, height and width of feature shape of each image in LLM.
        """
        pixel_values = pixel_values.type(self.visual.dtype)
        image_embeds, deepstack_image_embeds = self.visual(pixel_values, grid_thw=image_grid_thw)
        split_sizes = (image_grid_thw.prod(-1) // self.visual.spatial_merge_size**2).tolist()
        image_embeds = torch.split(image_embeds, split_sizes)
        return image_embeds, deepstack_image_embeds

    def get_placeholder_mask(
        self,
        input_ids: torch.LongTensor,
        inputs_embeds: torch.FloatTensor,
        image_features: Optional[torch.FloatTensor] = None,
        video_features: Optional[torch.FloatTensor] = None,
    ):
        """
        Obtains multimodal placeholder mask from `input_ids` or `inputs_embeds`, and checks that the placeholder token count is
        equal to the length of multimodal features. If the lengths are different, an error is raised.
        """
        """
        get_placeholder_mask 的作用就是：
        在多模态输入中，找出文本序列里哪些位置是“图像token占位符/视频token占位符”，
        并强制检查这些占位符的数量与提供的 image_features / video_features 
        完全一致，以防止“token 个数”和“视觉特征个数”对不上导致后面对齐出错。
        """
        if input_ids is None:
            # 只能从 inputs_embeds 里“反推”哪个位置是图像/视频 token, 进行lookup
            special_image_mask = inputs_embeds == self.get_input_embeddings()(
                torch.tensor(self.config.image_token_id, dtype=torch.long, device=inputs_embeds.device)
            )
            special_image_mask = special_image_mask.all(-1)
            special_video_mask = inputs_embeds == self.get_input_embeddings()(
                torch.tensor(self.config.video_token_id, dtype=torch.long, device=inputs_embeds.device)
            )
            special_video_mask = special_video_mask.all(-1)
        else:
            # 直接在 token id 上比较：
            special_image_mask = input_ids == self.config.image_token_id
            special_video_mask = input_ids == self.config.video_token_id

        n_image_tokens = special_image_mask.sum()
        special_image_mask = special_image_mask.unsqueeze(-1).expand_as(inputs_embeds).to(inputs_embeds.device)
        if image_features is not None and inputs_embeds[special_image_mask].numel() != image_features.numel():
            raise ValueError(
                f"Image features and image tokens do not match: tokens: {n_image_tokens}, features {image_features.shape[0]}"
            )

        n_video_tokens = special_video_mask.sum()
        special_video_mask = special_video_mask.unsqueeze(-1).expand_as(inputs_embeds).to(inputs_embeds.device)
        if video_features is not None and inputs_embeds[special_video_mask].numel() != video_features.numel():
            raise ValueError(
                f"Videos features and video tokens do not match: tokens: {n_video_tokens}, features {video_features.shape[0]}"
            )
        
        # 找到image token的位置
        return special_image_mask, special_video_mask

    @auto_docstring
    @check_model_inputs
    def forward(
        self,
        input_ids: torch.LongTensor = None,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        position_input_ids: Optional[torch.LongTensor] = None,
        qwen_position_contract: str = "historical_inputs_embeds_1d",
        past_key_values: Optional[Cache] = None,
        inputs_embeds: Optional[torch.FloatTensor] = None,
        pixel_values: Optional[torch.Tensor] = None,
        pixel_values_videos: Optional[torch.FloatTensor] = None,
        image_grid_thw: Optional[torch.LongTensor] = None,
        video_grid_thw: Optional[torch.LongTensor] = None,
        cache_position: Optional[torch.LongTensor] = None,
        dinov3_qkv_states: Optional[dict] = None,  # {qwen_layer: {'query', 'key', 'value'}}
        dinov3_qwen_mapping: Optional[dict] = None,  # {qwen_layer: dinov3_layer}
        # Efficient mode: DinoV3 called inside the model after pruning
        dinov3_model: Optional[nn.Module] = None,
        dinov3_aligner: Optional[nn.Module] = None,
        dinov3_pixel_values: Optional[torch.Tensor] = None,
        dinov3_efficient: bool = False,
        dinov3_qkv_after_rope: bool = True,
        train_dinov3_full_finetune: bool = False,
        **kwargs: Unpack[TransformersKwargs],
    ) -> Union[tuple, Qwen3VLModelOutputWithPast]:
        r"""
        image_grid_thw (`torch.LongTensor` of shape `(num_images, 3)`, *optional*):
            The temporal, height and width of feature shape of each image in LLM.
        video_grid_thw (`torch.LongTensor` of shape `(num_videos, 3)`, *optional*):
            The temporal, height and width of feature shape of each video in LLM.
        position_input_ids (`torch.LongTensor` of shape `(batch_size, sequence_length)`, *optional*):
            Token IDs paired with `inputs_embeds` so native multimodal mRoPE coordinates can be reconstructed.
        qwen_position_contract (`str`, *optional*, defaults to `"historical_inputs_embeds_1d"`):
            Positioning behavior for the `inputs_embeds` path. `"token_ids_mrope"` requires
            `position_input_ids` and preserves Qwen multimodal mRoPE.
        dinov3_qkv_states (`dict`, *optional*):
            Pre-computed Q/K/V states from DINOv3 encoder for the language model (token pruning / cross-modal).
            Only used in normal mode (dinov3_efficient=False).
        dinov3_qwen_mapping (`dict`, *optional*):
            Mapping from Qwen decoder layer indices to DINOv3 layer indices.
        dinov3_model (`nn.Module`, *optional*):
            DINOv3 model for efficient mode. When provided with dinov3_efficient=True,
            the model will call DinoV3 internally after determining pruning indices.
        dinov3_aligner (`nn.Module`, *optional*):
            Module that aligns DINOv3 query, key, and value tensors to Qwen attention geometry.
        dinov3_pixel_values (`torch.Tensor`, *optional*):
            Pixel values for DINOv3 input (for efficient mode).
        dinov3_efficient (`bool`, defaults to False):
            If True, use efficient mode where DinoV3 is called inside the model after pruning.
        dinov3_qkv_after_rope (`bool`, defaults to True):
            Extract QKV after RoPE (for efficient mode).
        train_dinov3_full_finetune (`bool`, defaults to False):
            Whether DinoV3 is in training mode (for efficient mode).
        """
        supported_position_contracts = {
            "historical_inputs_embeds_1d",
            "token_ids_mrope",
        }
        if qwen_position_contract not in supported_position_contracts:
            raise ValueError(
                "qwen_position_contract must be one of "
                f"{sorted(supported_position_contracts)}; got {qwen_position_contract!r}."
            )
        if (input_ids is None) ^ (inputs_embeds is not None):
            raise ValueError("You must specify exactly one of input_ids or inputs_embeds")

        using_inputs_embeds = inputs_embeds is not None
        if position_input_ids is not None:
            if not using_inputs_embeds:
                raise ValueError("position_input_ids is only valid when inputs_embeds is provided.")
            if position_input_ids.ndim != 2 or tuple(position_input_ids.shape) != tuple(inputs_embeds.shape[:2]):
                raise ValueError(
                    "position_input_ids must have the same batch and sequence shape as inputs_embeds; "
                    f"got position_input_ids={tuple(position_input_ids.shape)} "
                    f"inputs_embeds={tuple(inputs_embeds.shape)}."
                )
        if (
            using_inputs_embeds
            and position_ids is None
            and qwen_position_contract == "token_ids_mrope"
            and position_input_ids is None
        ):
            raise ValueError(
                "qwen_position_contract='token_ids_mrope' with inputs_embeds requires "
                "position_input_ids so multimodal RoPE can be computed from token IDs."
            )

        rope_input_ids = input_ids
        if using_inputs_embeds and qwen_position_contract == "token_ids_mrope":
            rope_input_ids = position_input_ids.to(inputs_embeds.device)

        if inputs_embeds is None:
            inputs_embeds = self.get_input_embeddings()(input_ids)

        image_mask = None
        video_mask = None

        if pixel_values is not None:
            image_embeds, deepstack_image_embeds = self.get_image_features(pixel_values, image_grid_thw)
            image_embeds = torch.cat(image_embeds, dim=0).to(inputs_embeds.device, inputs_embeds.dtype)
            image_mask, _ = self.get_placeholder_mask(
                input_ids, inputs_embeds=inputs_embeds, image_features=image_embeds
            )
            # [b,n,d] = [4, 279, 2560], 最后action dim * action chunk = 0, 第一层
            # 前面有一些padding
            inputs_embeds = inputs_embeds.masked_scatter(image_mask, image_embeds)

        if pixel_values_videos is not None:
            video_embeds, deepstack_video_embeds = self.get_video_features(pixel_values_videos, video_grid_thw)
            video_embeds = torch.cat(video_embeds, dim=0).to(inputs_embeds.device, inputs_embeds.dtype)
            _, video_mask = self.get_placeholder_mask(
                input_ids, inputs_embeds=inputs_embeds, video_features=video_embeds
            )
            inputs_embeds = inputs_embeds.masked_scatter(video_mask, video_embeds)

        visual_pos_masks = None
        deepstack_visual_embeds = None
        if image_mask is not None and video_mask is not None:
            # aggregate visual_pos_masks and deepstack_visual_embeds
            image_mask = image_mask[..., 0]
            video_mask = video_mask[..., 0]
            visual_pos_masks = image_mask | video_mask
            deepstack_visual_embeds = []
            image_mask_joint = image_mask[visual_pos_masks]
            video_mask_joint = video_mask[visual_pos_masks]
            for img_embed, vid_embed in zip(deepstack_image_embeds, deepstack_video_embeds):
                embed_joint = img_embed.new_zeros(visual_pos_masks.sum(), img_embed.shape[-1]).to(img_embed.device)
                embed_joint[image_mask_joint, :] = img_embed
                embed_joint[video_mask_joint, :] = vid_embed
                deepstack_visual_embeds.append(embed_joint)
        elif image_mask is not None:
            # [4, 279, 2560] -> [4, 279]
            image_mask = image_mask[..., 0]
            visual_pos_masks = image_mask
            deepstack_visual_embeds = deepstack_image_embeds
        elif video_mask is not None:
            video_mask = video_mask[..., 0]
            visual_pos_masks = video_mask
            deepstack_visual_embeds = deepstack_video_embeds

        if position_ids is None:
            # [4, 279]
            attention_mask_tensor = (
                attention_mask if not isinstance(attention_mask, dict) else attention_mask["full_attention"]
            )
            if attention_mask_tensor is not None and attention_mask_tensor.ndim == 4:
                attention_mask_tensor = torch.diagonal(attention_mask_tensor[:, 0], dim1=1, dim2=2)
                # Only apply conversion for floating point tensors (inverted masks)
                if attention_mask_tensor.dtype.is_floating_point:
                    attention_mask_tensor = attention_mask_tensor / torch.finfo(attention_mask_tensor.dtype).min
                    attention_mask_tensor = (1.0 - attention_mask_tensor).int()

            # Calculate RoPE index once per generation in the pre-fill stage only.
            # When compiling, we can't check tensor values thus we check only input length
            # It is safe to assume that `length!=1` means we're in pre-fill because compiled
            # models currently cannot do asssisted decoding
            # 在 Qwen3-VL 的 forward 中，根据当前是否处于预填充阶段或增量解码阶段，
            # 智能地计算或复用 RoPE 的位置索引（position_ids 和 rope_deltas），
            # 以支持带 KV cache 的高效长序列自回归推理，
            # 同时兼容 TorchDynamo 编译模式和多模态（文本+图像/视频）场景。
            prefill_compiled_stage = is_torchdynamo_compiling() and (
                (input_ids is not None and input_ids.shape[1] != 1)
                or (inputs_embeds is not None and inputs_embeds.shape[1] != 1)
            )
            prefill_noncompiled_stage = not is_torchdynamo_compiling() and (
                (cache_position is not None and cache_position[0] == 0)
                or (past_key_values is None or past_key_values.get_seq_length() == 0)
            )
            if (prefill_compiled_stage or prefill_noncompiled_stage) or self.rope_deltas is None:
                position_ids, rope_deltas = self.get_rope_index(
                    rope_input_ids,
                    image_grid_thw,
                    video_grid_thw,
                    attention_mask=attention_mask_tensor,
                )
                self.rope_deltas = rope_deltas
            # then use the prev pre-calculated rope-deltas to get the correct position ids
            else:
                batch_size, seq_length, _ = inputs_embeds.shape
                delta = (
                    (cache_position[0] + self.rope_deltas).to(inputs_embeds.device)
                    if cache_position is not None
                    else 0
                )
                position_ids = torch.arange(seq_length, device=inputs_embeds.device)
                position_ids = position_ids.view(1, -1).expand(batch_size, -1)
                if cache_position is not None:  # otherwise `deltas` is an int `0`
                    delta = delta.repeat_interleave(batch_size // delta.shape[0], dim=0)
                position_ids = position_ids.add(delta)
                position_ids = position_ids.unsqueeze(0).expand(3, -1, -1)

        # 计算 dinov3_len（如果有的话）
        dinov3_len = 0
        expert_num_prefix_tokens = kwargs.pop('expert_num_prefix_tokens', None)
        expert_patch_grid_contract = kwargs.pop('expert_patch_grid_contract', 'strict_square')
        expert_token_order = kwargs.pop('expert_token_order', 'importance')
        vl_position_contract = kwargs.pop(
            'vl_position_contract',
            'historical_expert_offset_all_layers',
        )
        pruning_attention_index_contract = kwargs.pop(
            'pruning_attention_index_contract',
            'historical_base_indices',
        )
        pruning_layer_index_base = kwargs.pop('pruning_layer_index_base', 'zero')
        action_task_attention_contract = kwargs.pop(
            'action_task_attention_contract',
            'historical_joint_mean',
        )
        attention_collection_mask_contract = kwargs.pop(
            'attention_collection_mask_contract',
            'historical_sdpa_eager_mismatch',
        )
        vla_attention_mask_contract = kwargs.pop(
            'vla_attention_mask_contract',
            'historical_causal',
        )
        expert_private_to_action = int(kwargs.pop('expert_private_to_action', 0))
        dinov3_num_register_tokens = kwargs.pop('dinov3_num_register_tokens', 4)
        if expert_num_prefix_tokens is None:
            expert_num_prefix_tokens = 1 + int(dinov3_num_register_tokens)
        expert_num_prefix_tokens = int(expert_num_prefix_tokens)
        if expert_num_prefix_tokens < 0:
            raise ValueError(
                f"expert_num_prefix_tokens must be non-negative; got {expert_num_prefix_tokens}."
            )
        if dinov3_qkv_states is not None and len(dinov3_qkv_states) > 0:
            # 获取 dinov3 的长度（从第一层的 QKV 中获取）
            first_layer_qkv = next(iter(dinov3_qkv_states.values()))
            dinov3_len = first_layer_qkv['query'].shape[2]  # [batch, num_heads, seq_len, head_dim]
        elif dinov3_efficient and dinov3_pixel_values is not None:
            # Pass the unpruned expert length to the text model. The text model
            # is the single owner of the pruning-ratio calculation.
            patch_size = 16
            if hasattr(dinov3_model, 'config') and hasattr(dinov3_model.config, 'patch_size'):
                patch_size = dinov3_model.config.patch_size
            num_patches_h, num_patches_w = _expert_patch_grid_from_pixels(
                dinov3_pixel_values,
                patch_size,
            )
            dinov3_len = expert_num_prefix_tokens + num_patches_h * num_patches_w

        # 从 kwargs 中提取 pruning 参数和其他辅助参数
        pruning_mode = kwargs.pop('pruning_mode', 'none')
        pruning_ref_layer = kwargs.pop('pruning_ref_layer', None)
        pruning_ratio = kwargs.pop('pruning_ratio', 0.0)
        action_length = kwargs.pop('action_length', 0)
        prefix_tokens_lens = kwargs.pop('prefix_tokens_lens', None)
        instruction_ranges = kwargs.pop('instruction_ranges', None)
        collect_attention_maps = kwargs.pop('collect_attention_maps', False)
        # 多层聚合剪枝参数
        pruning_attn_aggregation = kwargs.pop('pruning_attn_aggregation', 'none')
        pruning_attn_aggregation_layer_start = kwargs.pop('pruning_attn_aggregation_layer_start', 3)
        pruning_attn_aggregation_layer_end = kwargs.pop('pruning_attn_aggregation_layer_end', 10)
        pruning_attn_aggregation_vote_ratio = kwargs.pop('pruning_attn_aggregation_vote_ratio', 0.6)
        pruning_vote_contract = kwargs.pop(
            'pruning_vote_contract',
            'historical_floor_global_fallback',
        )
        # action-image attention restriction
        action_img_attn_start_layer = kwargs.pop('action_img_attn_start_layer', -1)
        action_attn_mode = kwargs.pop('action_attn_mode', 'none')
        action_attn_roi_layer_start = kwargs.pop('action_attn_roi_layer_start', 3)
        action_attn_roi_layer_end = kwargs.pop('action_attn_roi_layer_end', 10)
        action_attn_roi_ratio = kwargs.pop('action_attn_roi_ratio', 0.5)
        # 允许调用者通过 kwargs 传入 visual_pos_masks（例如 SigLIP MOT 模式下 pixel_values=None）
        visual_pos_masks = kwargs.pop('visual_pos_masks', visual_pos_masks)

        outputs = self.language_model(
            input_ids=None,
            position_ids=position_ids,  # [3, 4, 279], 3: THW, 1D text 3维都一样
            attention_mask=attention_mask,  # [4, 279], 能定位padding
            past_key_values=past_key_values,  # None, oft里面不会用到kv cache
            inputs_embeds=inputs_embeds,  # [4, 279, 2560]
            cache_position=cache_position,  # None
            visual_pos_masks=visual_pos_masks,  # [4, 279], 定位视觉token位置, 标记True
            deepstack_visual_embeds=deepstack_visual_embeds,  # 3x[1024, 2560]
            dinov3_qkv_states=dinov3_qkv_states,  # q: [4, 32, 1029, 128], kv: [4, 8, 1029, 128]（随分辨率）
            dinov3_qwen_mapping=dinov3_qwen_mapping,
            dinov3_len=dinov3_len,  # = expert_num_prefix_tokens + num_patches（随分辨率；当前 1+4+1024=1029）
            pruning_mode=pruning_mode,
            pruning_ref_layer=pruning_ref_layer,
            pruning_ratio=pruning_ratio,
            action_length=action_length,
            prefix_tokens_lens=prefix_tokens_lens,
            instruction_ranges=instruction_ranges,
            dinov3_num_register_tokens=dinov3_num_register_tokens,
            expert_num_prefix_tokens=expert_num_prefix_tokens,
            expert_patch_grid_contract=expert_patch_grid_contract,
            expert_token_order=expert_token_order,
            vl_position_contract=vl_position_contract,
            pruning_attention_index_contract=pruning_attention_index_contract,
            pruning_layer_index_base=pruning_layer_index_base,
            action_task_attention_contract=action_task_attention_contract,
            attention_collection_mask_contract=attention_collection_mask_contract,
            vla_attention_mask_contract=vla_attention_mask_contract,
            expert_private_to_action=expert_private_to_action,
            collect_attention_maps=collect_attention_maps,
            output_hidden_states=kwargs.pop('output_hidden_states', None),
            # Efficient mode parameters
            dinov3_model=dinov3_model,
            dinov3_aligner=dinov3_aligner,
            dinov3_pixel_values=dinov3_pixel_values,
            dinov3_efficient=dinov3_efficient,
            dinov3_qkv_after_rope=dinov3_qkv_after_rope,
            train_dinov3_full_finetune=train_dinov3_full_finetune,
            pruning_attn_aggregation=pruning_attn_aggregation,
            pruning_attn_aggregation_layer_start=pruning_attn_aggregation_layer_start,
            pruning_attn_aggregation_layer_end=pruning_attn_aggregation_layer_end,
            pruning_attn_aggregation_vote_ratio=pruning_attn_aggregation_vote_ratio,
            pruning_vote_contract=pruning_vote_contract,
            action_img_attn_start_layer=action_img_attn_start_layer,
            action_attn_mode=action_attn_mode,
            action_attn_roi_layer_start=action_attn_roi_layer_start,
            action_attn_roi_layer_end=action_attn_roi_layer_end,
            action_attn_roi_ratio=action_attn_roi_ratio,
            **kwargs,
        )

        return Qwen3VLModelOutputWithPast(
            last_hidden_state=outputs.last_hidden_state,
            past_key_values=outputs.past_key_values,
            hidden_states=outputs.hidden_states,
            rope_deltas=self.rope_deltas,
            attention_map_resized=getattr(outputs, "attention_map_resized", None),
            attention_to_visual_all_layers=getattr(outputs, "attention_to_visual_all_layers", None),
            attention_map_resized_all_layers=getattr(outputs, "attention_map_resized_all_layers", None),
            aggregated_attention_to_visual=getattr(outputs, "aggregated_attention_to_visual", None),
        )


@dataclass
@auto_docstring(
    custom_intro="""
    Base class for Qwen3VL causal language model (or autoregressive) outputs.
    """
)
class Qwen3VLCausalLMOutputWithPast(ModelOutput):
    r"""
    loss (`torch.FloatTensor` of shape `(1,)`, *optional*, returned when `labels` is provided):
        Language modeling loss (for next-token prediction).
    logits (`torch.FloatTensor` of shape `(batch_size, sequence_length, config.vocab_size)`):
        Prediction scores of the language modeling head (scores for each vocabulary token before SoftMax).
    past_key_values (`Cache`, *optional*, returned when `use_cache=True` is passed or when `config.use_cache=True`):
        It is a [`~cache_utils.Cache`] instance. For more details, see our [kv cache guide](https://huggingface.co/docs/transformers/en/kv_cache).

        Contains pre-computed hidden-states (key and values in the self-attention blocks) that can be used (see
        `past_key_values` input) to speed up sequential decoding.
    rope_deltas (`torch.LongTensor` of shape `(batch_size, )`, *optional*):
        The rope index difference between sequence length and multimodal rope.
    """

    loss: Optional[torch.FloatTensor] = None
    logits: Optional[torch.FloatTensor] = None
    past_key_values: Optional[Cache] = None
    hidden_states: Optional[tuple[torch.FloatTensor]] = None
    attentions: Optional[tuple[torch.FloatTensor]] = None
    rope_deltas: Optional[torch.LongTensor] = None


class Qwen3VLForConditionalGeneration(Qwen3VLPreTrainedModel, GenerationMixin):
    _checkpoint_conversion_mapping = {}
    _tied_weights_keys = ["lm_head.weight"]
    # Reference: fix gemma3 grad acc #37208
    accepts_loss_kwargs = False
    config: Qwen3VLConfig

    def __init__(self, config):
        super().__init__(config)
        self.model = Qwen3VLModel(config)
        self.lm_head = nn.Linear(config.text_config.hidden_size, config.text_config.vocab_size, bias=False)

        self.post_init()

    def get_input_embeddings(self):
        return self.model.get_input_embeddings()

    def set_input_embeddings(self, value):
        self.model.set_input_embeddings(value)

    def set_decoder(self, decoder):
        self.model.set_decoder(decoder)

    def get_decoder(self):
        return self.model.get_decoder()

    def get_video_features(
        self, pixel_values_videos: torch.FloatTensor, video_grid_thw: Optional[torch.LongTensor] = None
    ):
        return self.model.get_video_features(pixel_values_videos, video_grid_thw)

    def get_image_features(self, pixel_values: torch.FloatTensor, image_grid_thw: Optional[torch.LongTensor] = None):
        return self.model.get_image_features(pixel_values, image_grid_thw)

    # Make modules available through conditional class for BC
    @property
    def language_model(self):
        return self.model.language_model

    @property
    def visual(self):
        return self.model.visual

    @check_model_inputs
    def forward(
        self,
        input_ids: torch.LongTensor = None,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        position_input_ids: Optional[torch.LongTensor] = None,
        qwen_position_contract: str = "historical_inputs_embeds_1d",
        past_key_values: Optional[Cache] = None,
        inputs_embeds: Optional[torch.FloatTensor] = None,
        labels: Optional[torch.LongTensor] = None,
        pixel_values: Optional[torch.Tensor] = None,
        pixel_values_videos: Optional[torch.FloatTensor] = None,
        image_grid_thw: Optional[torch.LongTensor] = None,
        video_grid_thw: Optional[torch.LongTensor] = None,
        cache_position: Optional[torch.LongTensor] = None,
        logits_to_keep: Union[int, torch.Tensor] = 0,
        **kwargs: Unpack[TransformersKwargs],
    ) -> Union[tuple, Qwen3VLCausalLMOutputWithPast]:
        r"""
        labels (`torch.LongTensor` of shape `(batch_size, sequence_length)`, *optional*):
            Labels for computing the masked language modeling loss. Indices should either be in `[0, ...,
            config.vocab_size]` or -100 (see `input_ids` docstring). Tokens with indices set to `-100` are ignored
            (masked), the loss is only computed for the tokens with labels in `[0, ..., config.vocab_size]`.
        image_grid_thw (`torch.LongTensor` of shape `(num_images, 3)`, *optional*):
            The temporal, height and width of feature shape of each image in LLM.
        video_grid_thw (`torch.LongTensor` of shape `(num_videos, 3)`, *optional*):
            The temporal, height and width of feature shape of each video in LLM.

        Example:
            TODO: Add example
        """
        outputs = self.model(
            input_ids=input_ids,
            pixel_values=pixel_values,
            pixel_values_videos=pixel_values_videos,
            image_grid_thw=image_grid_thw,
            video_grid_thw=video_grid_thw,
            position_ids=position_ids,
            position_input_ids=position_input_ids,
            qwen_position_contract=qwen_position_contract,
            attention_mask=attention_mask,
            past_key_values=past_key_values,
            inputs_embeds=inputs_embeds,
            cache_position=cache_position,
            **kwargs,
        )

        hidden_states = outputs[0]

        # Only compute necessary logits, and do not upcast them to float if we are not computing the loss
        slice_indices = slice(-logits_to_keep, None) if isinstance(logits_to_keep, int) else logits_to_keep
        logits = self.lm_head(hidden_states[:, slice_indices, :])

        loss = None
        if labels is not None:
            loss = self.loss_function(logits=logits, labels=labels, vocab_size=self.config.text_config.vocab_size)

        return Qwen3VLCausalLMOutputWithPast(
            loss=loss,
            logits=logits,
            past_key_values=outputs.past_key_values,
            rope_deltas=outputs.rope_deltas,
        )

    def prepare_inputs_for_generation(
        self,
        input_ids,
        past_key_values=None,
        attention_mask=None,
        inputs_embeds=None,
        cache_position=None,
        position_ids=None,
        use_cache=True,
        pixel_values=None,
        pixel_values_videos=None,
        image_grid_thw=None,
        video_grid_thw=None,
        **kwargs,
    ):
        # Overwritten -- in specific circumstances we don't want to forward image inputs to the model

        model_inputs = super().prepare_inputs_for_generation(
            input_ids,
            past_key_values=past_key_values,
            attention_mask=attention_mask,
            inputs_embeds=inputs_embeds,
            cache_position=cache_position,
            position_ids=position_ids,
            pixel_values=pixel_values,
            pixel_values_videos=pixel_values_videos,
            image_grid_thw=image_grid_thw,
            video_grid_thw=video_grid_thw,
            use_cache=use_cache,
            **kwargs,
        )

        # Qwen3VL position_ids are prepareed with rope_deltas in forward
        model_inputs["position_ids"] = None

        if cache_position[0] != 0:
            model_inputs["pixel_values"] = None
            model_inputs["pixel_values_videos"] = None

        return model_inputs

    def _get_image_nums_and_video_nums(
        self,
        input_ids: Optional[torch.LongTensor],
        inputs_embeds: Optional[torch.Tensor] = None,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        """
        Get the number of images and videos for each sample to calculate the separation length of the sample tensor.
        These parameters are not passed through the processor to avoid unpredictable impacts from interface modifications.

        Args:
            input_ids (`torch.LongTensor` of shape `(batch_size, sequence_length)`):
                Indices of input sequence tokens in the vocabulary.

        Returns:
            image_nums (`torch.LongTensor` of shape `(batch_size, num_images_sample)`)
            video_nums (`torch.LongTensor` of shape `(batch_size, num_videos_sample)`)
        """
        image_token_id = self.config.image_token_id
        video_token_id = self.config.video_token_id
        vision_start_token_id = self.config.vision_start_token_id

        if inputs_embeds is not None:
            vision_start_mask = (
                inputs_embeds
                == self.get_input_embeddings()(
                    torch.tensor(vision_start_token_id, dtype=torch.long, device=inputs_embeds.device)
                )
            )[..., 0]
            image_mask = (
                inputs_embeds
                == self.get_input_embeddings()(
                    torch.tensor(image_token_id, dtype=torch.long, device=inputs_embeds.device)
                )
            )[..., 0]
            video_mask = (
                inputs_embeds
                == self.get_input_embeddings()(
                    torch.tensor(video_token_id, dtype=torch.long, device=inputs_embeds.device)
                )
            )[..., 0]
        else:
            vision_start_mask = input_ids == vision_start_token_id
            image_mask = input_ids == image_token_id
            video_mask = input_ids == video_token_id

        vision_first_mask = torch.roll(vision_start_mask, shifts=1, dims=1)
        image_nums = torch.sum(vision_first_mask & image_mask, dim=1)
        video_nums = torch.sum(vision_first_mask & video_mask, dim=1)

        return image_nums, video_nums

    def _expand_inputs_for_generation(
        self,
        expand_size: int = 1,
        is_encoder_decoder: bool = False,
        input_ids: Optional[torch.LongTensor] = None,
        **model_kwargs,
    ) -> tuple[torch.LongTensor, dict[str, Any]]:
        # Overwritten -- Support for expanding tensors without a batch size dimension
        # e.g., pixel_values, image_grid_thw, pixel_values_videos, video_grid_thw, second_per_grid_t
        # pixel_values.shape[0] is sum(seqlen_images for samples)
        # image_grid_thw.shape[0] is sum(num_images for samples)

        if expand_size == 1:
            return input_ids, model_kwargs

        visual_keys = ["pixel_values", "image_grid_thw", "pixel_values_videos", "video_grid_thw", "second_per_grid_ts"]

        def _expand_dict_for_generation_visual(dict_to_expand):
            image_grid_thw = model_kwargs.get("image_grid_thw", None)
            video_grid_thw = model_kwargs.get("video_grid_thw", None)
            image_nums, video_nums = self._get_image_nums_and_video_nums(
                input_ids, inputs_embeds=model_kwargs.get("inputs_embeds", None)
            )

            def _repeat_interleave_samples(x, lengths, repeat_times):
                samples = torch.split(x, lengths)
                repeat_args = [repeat_times] + [1] * (x.dim() - 1)
                result = torch.cat([sample.repeat(*repeat_args) for sample in samples], dim=0)
                return result

            for key in dict_to_expand:
                if key == "pixel_values":
                    # split images into samples
                    samples = torch.split(image_grid_thw, list(image_nums))
                    # compute the sequence length of images for each sample
                    lengths = [torch.prod(sample, dim=1).sum() for sample in samples]
                    dict_to_expand[key] = _repeat_interleave_samples(
                        dict_to_expand[key], lengths=lengths, repeat_times=expand_size
                    )
                elif key == "image_grid_thw":
                    # get the num of images for each sample
                    lengths = list(image_nums)
                    dict_to_expand[key] = _repeat_interleave_samples(
                        dict_to_expand[key], lengths=lengths, repeat_times=expand_size
                    )
                elif key == "pixel_values_videos":
                    samples = torch.split(video_grid_thw, list(video_nums))
                    lengths = [torch.prod(sample, dim=1).sum() for sample in samples]
                    dict_to_expand[key] = _repeat_interleave_samples(
                        dict_to_expand[key], lengths=lengths, repeat_times=expand_size
                    )
                elif key == "video_grid_thw":
                    lengths = list(video_nums)
                    dict_to_expand[key] = _repeat_interleave_samples(
                        dict_to_expand[key], lengths=lengths, repeat_times=expand_size
                    )
                elif key == "second_per_grid_ts":
                    dict_to_expand[key] = _repeat_interleave_samples(
                        dict_to_expand[key], lengths=list(video_nums), repeat_times=expand_size
                    )
            return dict_to_expand

        def _expand_dict_for_generation(dict_to_expand):
            for key in dict_to_expand:
                if (
                    key != "cache_position"
                    and dict_to_expand[key] is not None
                    and isinstance(dict_to_expand[key], torch.Tensor)
                    and key not in visual_keys
                ):
                    dict_to_expand[key] = dict_to_expand[key].repeat_interleave(expand_size, dim=0)
            return dict_to_expand

        model_kwargs = _expand_dict_for_generation_visual(model_kwargs)

        if input_ids is not None:
            input_ids = input_ids.repeat_interleave(expand_size, dim=0)

        model_kwargs = _expand_dict_for_generation(model_kwargs)

        if is_encoder_decoder:
            if model_kwargs.get("encoder_outputs") is None:
                raise ValueError("If `is_encoder_decoder` is True, make sure that `encoder_outputs` is defined.")
            model_kwargs["encoder_outputs"] = _expand_dict_for_generation(model_kwargs["encoder_outputs"])

        return input_ids, model_kwargs


__all__ = [
    "Qwen3VLVisionModel",
    "Qwen3VLForConditionalGeneration",
    "Qwen3VLModel",
    "Qwen3VLPreTrainedModel",
    "Qwen3VLTextModel",
]
